"""Final, source-owned protected SQL interfaces installed by the controlled migrator.

Headers and bodies are explicit data. No parser reads bootstrap source or
accepts predecessor body variants at runtime. Catalog proof precedes mutation;
ordinary serving pools never import an installer entry point.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class FunctionDefinition:
    schema: str
    name: str
    signature: str
    owner: str
    executors: tuple[str, ...]
    security_definer: bool
    header: str
    body: str

    @property
    def identity(self) -> tuple[str, str, str]:
        return self.schema, self.name, self.signature

    @property
    def sql(self) -> str:
        return self.header + "AS $db_authority_body$" + self.body + "$db_authority_body$;"


