            "            OR p_confidence IS NOT NULL OR p_metadata IS NOT NULL) THEN\n"
            "        RAISE EXCEPTION 'DND clear cannot carry set payload fields';\n"
            "    END IF;\n"
            "    IF p_operation = 'set'\n"
            "       AND (p_confidence IS NULL OR p_confidence < 0.0 OR p_confidence > 1"
