def require_maintenance(connection) -> None:
    """Prove the explicitly selected operator prerequisite before protected DDL."""
    from .roles import AuthorityError

    if (
        connection.exec_driver_sql(
            "SELECT current_user=session_user AND rolsuper "
            "FROM pg_catalog.pg_roles WHERE rolname=session_user"
        ).scalar_one()
        is not True
    ):
        raise AuthorityError("Protected interface maintenance prerequisite is unavailable")


def _protected_group_state(connection, group: str, *, profiles=None) -> bool:
    from sqlalchemy import text

    from .roles import AuthorityError

    present = []
    for schema, name, owner in _PROTECTED_GROUPS[group]:
        row = (
            connection.execute(
                text(
                    "\n"
                    "            SELECT c.relkind, role.rolname AS owner\n"
                    "            FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespa"
                    "ce n ON n.oid=c.relnamespace\n"
                    "            JOIN pg_catalog.pg_roles role ON role.oid=c.relowner"
                    "\n"
                    "            WHERE n.nspname=:schema AND c.relname=:name\n"
                    "        "
                ),
                {"schema": schema, "name": name},
            )
            .mappings()
            .one_or_none()
        )
        present.append(row is not None)
        if row is not None and (row["relkind"] != "r" or row["owner"] != owner):
            raise AuthorityError("Protected relation ownership prerequisite is unavailable")
    if any(present) and not all(present):
        raise AuthorityError("Protected database state is incomplete")
    if all(present):
        verify_protected_relation_shapes(connection, group, profiles=profiles)
    return all(present)


def _attention_stage(connection, *, profiles=None) -> int:
    """Recognize only exact delivered historical states before additive work."""
    from sqlalchemy import text

    from .roles import AuthorityError

    present = set()
    for schema, name, owner in _PROTECTED_GROUPS["attention"]:
        row = (
            connection.execute(
                text("""SELECT c.relkind, r.rolname AS owner FROM pg_catalog.pg_class c
            JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
            JOIN pg_catalog.pg_roles r ON r.oid=c.relowner
            WHERE n.nspname=:schema AND c.relname=:name"""),
                {"schema": schema, "name": name},
            )
            .mappings()
            .one_or_none()
        )
        if row is not None:
            if row != {"relkind": "r", "owner": owner}:
                raise AuthorityError("Attention predecessor ownership differs")
            present.add(name)
    if not present:
        return 0
    stages = [stage for stage, names in _ATTENTION_STAGE_NAMES.items() if present == names]
    if not stages:
        raise AuthorityError("Attention predecessor population is not source-owned")
    stage = min(stages)
    if stage == 4:
        marker = connection.execute(
            text("""SELECT EXISTS(SELECT FROM pg_catalog.pg_trigger
            WHERE tgrelid='public.runtime_attention_outbox'::regclass
              AND tgname='runtime_attention_condition_marker_sync_trigger')""")
        ).scalar_one()
        if marker is True:
            stage = 5
    verify_protected_relation_shapes(
        connection, "attention", attention_stage=stage, profiles=profiles
    )
    return stage


def _advance_attention_tables(connection, stage: int) -> None:
    """Create only missing fixed controls; never reset retained switches/receipts."""
    from .apply import quote_identifier

    present = _ATTENTION_STAGE_NAMES[stage]
    for group, schema, name, body, indexes in _PROTECTED_TABLE_SHAPES:
        if group != "attention" or name in present:
            continue
        target = quote_identifier(schema) + "." + quote_identifier(name)
        connection.exec_driver_sql(f"CREATE TABLE {target} ({body})")
        connection.exec_driver_sql(f"ALTER TABLE {target} OWNER TO runtime_attention_outbox_owner")
        # Missing controls are source-defined new rows. Existing disabled
        # operator/producer controls are never touched by this path.
        values = {
            "runtime_attention_operator_control": "true,3,true",
            "runtime_attention_producer_control": "true,2,true,clock_timestamp()",
            "runtime_attention_condition_control": "true,4,true",
        }.get(name)
        if values is not None:
            connection.exec_driver_sql(f"INSERT INTO {target} VALUES ({values})")
        for ordinal, (unique, suffix) in enumerate(indexes):
            qualifier = "UNIQUE " if unique else ""
            index = quote_identifier(name + "_authority_" + str(ordinal))
            connection.exec_driver_sql(f"CREATE {qualifier}INDEX {index} ON {target} {suffix}")
    if stage < 4:
        connection.exec_driver_sql(_ATTENTION_FINAL_CONSTRAINTS)


def _finish_attention_upgrade(connection, stage: int) -> None:
    if stage < 4:
        target = "public.runtime_attention_condition_episodes"
        connection.exec_driver_sql(f"ALTER TABLE {target} ENABLE ROW LEVEL SECURITY")
        connection.exec_driver_sql(f"ALTER TABLE {target} FORCE ROW LEVEL SECURITY")
        _parse_security_shape(connection, target, "runtime_attention_condition_episodes")
    # The other guards/policies were verified as actual predecessor shapes.
    # Add just the final marker; CREATE refuses a concurrent/unknown duplicate.
    connection.exec_driver_sql(
        "CREATE TRIGGER runtime_attention_condition_marker_sync_trigger "
        "AFTER UPDATE OF lifecycle_state ON public.runtime_attention_outbox "
        "FOR EACH ROW WHEN (NEW.source='control_plane_condition' AND "
        "NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state) "
        "EXECUTE FUNCTION public.runtime_attention_sync_condition_marker()"
    )


_ATTENTION_POLICY_SQL = (
    "\n"
    "ALTER TABLE public.runtime_attention_outbox ENABLE ROW LEVEL SECURITY;\n"
    "ALTER TABLE public.runtime_attention_outbox FORCE ROW LEVEL SECURITY;\n"
    "ALTER TABLE public.runtime_attention_delivery_lease ENABLE ROW LEVEL SECURITY;\n"
    "ALTER TABLE public.runtime_attention_delivery_lease FORCE ROW LEVEL SECURITY;\n"
    "ALTER TABLE public.runtime_attention_condition_episodes ENABLE ROW LEVEL SECURITY;"
    "\n"
    "ALTER TABLE public.runtime_attention_condition_episodes FORCE ROW LEVEL SECURITY;"
    "\n"
    "CREATE POLICY runtime_attention_outbox_owner ON public.runtime_attention_outbox\n"
    " FOR ALL TO runtime_attention_outbox_owner USING(true) WITH CHECK(true);\n"
    "CREATE POLICY runtime_attention_outbox_switchboard ON public.runtime_attention_out"
    "box\n"
    " FOR ALL TO butler_switchboard_rw USING(public.runtime_attention_active_switchboar"
    "d_role())\n"
    " WITH CHECK(public.runtime_attention_active_switchboard_role());\n"
    "CREATE POLICY runtime_attention_delivery_lease_owner ON public.runtime_attention_d"
    "elivery_lease\n"
    " FOR ALL TO runtime_attention_outbox_owner USING(true) WITH CHECK(true);\n"
    "CREATE POLICY runtime_attention_delivery_lease_switchboard ON public.runtime_atten"
    "tion_delivery_lease\n"
    " FOR ALL TO butler_switchboard_rw USING(public.runtime_attention_active_switchboar"
    "d_role())\n"
    " WITH CHECK(public.runtime_attention_active_switchboard_role());\n"
    "CREATE POLICY runtime_attention_condition_episodes_owner\n"
    " ON public.runtime_attention_condition_episodes\n"
    " FOR ALL TO runtime_attention_outbox_owner USING(true) WITH CHECK(true);\n"
    "CREATE TRIGGER runtime_attention_outbox_guard_trigger\n"
    " BEFORE INSERT OR UPDATE OR DELETE ON public.runtime_attention_outbox\n"
    " FOR EACH ROW EXECUTE FUNCTION public.runtime_attention_outbox_guard();\n"
    "CREATE TRIGGER runtime_attention_delivery_lease_guard_trigger\n"
    " BEFORE INSERT OR UPDATE OR DELETE ON public.runtime_attention_delivery_lease\n"
    " FOR EACH ROW EXECUTE FUNCTION public.runtime_attention_delivery_lease_guard();\n"
    "CREATE TRIGGER runtime_attention_condition_marker_sync_trigger\n"
    " AFTER UPDATE OF lifecycle_state ON public.runtime_attention_outbox\n"
    " FOR EACH ROW WHEN (NEW.source='control_plane_condition'\n"
    "  AND NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state)\n"
    " EXECUTE FUNCTION public.runtime_attention_sync_condition_marker();\n"
)


def _attention_policy_sql(profiles):
    """Project the two fixed Switchboard policies only when that actor is declared."""
    from .roles import AuthorityError

    if "butler_switchboard_rw" in {profile.role for profile in profiles}:
        return _ATTENTION_POLICY_SQL
    statements = _ATTENTION_POLICY_SQL.split(";")
    excluded = [
        sql
        for sql in statements
        if sql.lstrip().startswith("CREATE POLICY runtime_attention_")
        and " FOR ALL TO butler_switchboard_rw " in sql.replace("\n", " ")
    ]
    if len(excluded) != 2:
        raise AuthorityError("Selected attention policy source is ambiguous")
    return ";".join(sql for sql in statements if sql not in excluded)


def protected_group_functions(profiles, operator: str, groups):
    """Bind only the fixed current definitions actually produced by these groups."""
    from .roles import AuthorityError

    if not set(groups) <= {"restore", "dnd", "attention"}:
        raise AuthorityError("Protected source group is not declared")
    return tuple(
        definition
        for definition in final_functions(profiles, operator)
        if (
            "attention" in groups
            and definition.schema == "public"
            and definition.name != "context_dnd_mutate"
        )
        or (
            "dnd" in groups
            and (
                definition.schema == "dnd_generation_private"
                or definition.name == "context_dnd_mutate"
            )
        )
        or ("restore" in groups and definition.schema == "restore_drill_executor")
    )


def selected_protected_functions(profiles, operator: str, plans):
    """Historical edges install final protected bodies, with closed serving ACLs.

    The actual checked-in core graph determines which groups can exist. This
    does not certify an old stamp as a current serving catalog or execute a
    later group just because its name was discovered in PostgreSQL.
    """
    from dataclasses import replace

    from butlers.migrations import get_chain_revision_path

    groups = set()
    for chain, _, revision in plans:
        if chain == "core":
            ancestors = get_chain_revision_path(chain, revision)
            for edge, group in (
                ("core_196", "restore"),
                ("core_197", "dnd"),
                ("core_198", "attention"),
            ):
                if edge in ancestors:
                    groups.add(group)
    definitions = protected_group_functions(profiles, operator, groups)
    if any(revision is not None for _, _, revision in plans):
        definitions = tuple(replace(row, executors=()) for row in definitions)
    return definitions


def install_protected_state(connection, profiles, operator: str, *, group: str | None = None):
    """Install the fixed protected state, never reseed an existing receipt/epoch.

    The caller is the controlled migrator holding the database lock. Existing
    ownership and complete group presence are checked before the first write;
    a partial or hostile object needs explicit operator recovery, not repair by
    a compatible-looking name. Administrative authority is a separate caller
    prerequisite, not a runtime-granted stored installer.
    """
    from .apply import quote_identifier
    from .roles import AuthorityError

    groups = tuple(_PROTECTED_GROUPS) if group is None else (group,)
    if any(value not in _PROTECTED_GROUPS for value in groups):
        raise AuthorityError("Protected source group is not declared")
    attention_stage = (
        _attention_stage(connection, profiles=profiles) if "attention" in groups else 0
    )
    states = {
        value: attention_stage == 5
        if value == "attention"
        else _protected_group_state(connection, value, profiles=profiles)
        for value in groups
    }
    if not all(states.values()):
        require_maintenance(connection)
    fresh_sql = {
        "dnd": _FRESH_DND_SQL,
        "attention": _FRESH_ATTENTION_SQL,
        "restore": _FRESH_RESTORE_SQL,
    }
    for value, installed in states.items():
        if installed:
            continue
        if value == "attention" and attention_stage:
            _advance_attention_tables(connection, attention_stage)
            continue
        connection.exec_driver_sql(fresh_sql[value])
        for schema, name, owner in _PROTECTED_GROUPS[value]:
            connection.exec_driver_sql(
                f"ALTER TABLE {quote_identifier(schema)}.{quote_identifier(name)} "
                f"OWNER TO {quote_identifier(owner)}"
            )
    definitions = protected_group_functions(profiles, operator, groups)
    if group is not None:
        # A selected historical edge stages bodies without serving EXECUTE;
        # only the full current-plan finalizer installs serving capabilities.
        from dataclasses import replace

        definitions = tuple(replace(row, executors=()) for row in definitions)
    install_functions(connection, definitions)
    if "attention" in states and not states["attention"]:
        if attention_stage:
            _finish_attention_upgrade(connection, attention_stage)
        else:
            connection.exec_driver_sql(_attention_policy_sql(profiles))
    for value in groups:
        if not _protected_group_state(connection, value, profiles=profiles):
            raise AuthorityError("Protected database state did not install")


def stage_dashboard_interfaces(connection) -> None:
    """Stage the independent D13 installers under the held maintenance actor.

    These are later dashboard mechanisms, not the three retired admin bunkers.
    Their existing source-owned markers and isolated owners are checked by the
    fixed SQL before staging; the ordinary migration owner can invoke only the
    no-input interfaces. The selected owner comes from the actual database.
    """
    from sqlalchemy import text

    from butlers.migrations import maintenance_profile

    owner = maintenance_profile(connection)
    require_maintenance(connection)
    previous = connection.exec_driver_sql(
        "SELECT current_setting('butlers.connecting_user', true)"
    ).scalar_one()
    connection.execute(
        text("SELECT pg_catalog.set_config('butlers.connecting_user', :owner, true)"),
        {"owner": owner},
    )
    primary = None
    try:
        connection.exec_driver_sql(DASHBOARD_PURPOSE_SQL.replace("%", "%%"))
    except BaseException as exc:
        primary = exc
        raise
    finally:
        try:
            connection.execute(
                text("SELECT pg_catalog.set_config('butlers.connecting_user', :owner, true)"),
                {"owner": previous or ""},
            )
        except BaseException:
            if primary is None:
                raise
            primary.add_note("Dashboard maintenance identity restoration was incomplete")


def install_revision_group(connection, group: str) -> None:
    """Historical edges call the one current installer on the same held session.

    Ordinary chain DDL runs as the normal database owner. Only this source-owned
    maintenance call temporarily restores the independently verified privileged
    session actor. A normal login cannot gain that authority by RESET ROLE.
    """
    from butlers.migrations import maintenance_profile

    from .apply import quote_identifier
    from .roles import compile_deployment_profiles

    owner = maintenance_profile(connection)
    database, previous = connection.exec_driver_sql("SELECT current_database(), current_user").one()
    source = connection.info.get("butlers.source_database", database)
    profiles = compile_deployment_profiles(database, source_database=source)
    connection.exec_driver_sql("RESET ROLE")
    primary = None
    try:
        # Historical edges must enforce the same provenance boundary as the
        # final edge before creating protected state. A discovered admin name
        # (including a no-op imitation) grants no repair/install authority.
        inspect_retired_interfaces(connection, owner)
        install_protected_state(connection, profiles, owner, group=group)
    except BaseException as exc:
        primary = exc
        raise
    finally:
        try:
            connection.exec_driver_sql(f"SET ROLE {quote_identifier(previous)}")
        except BaseException:
            if primary is None:
                raise
            primary.add_note("Protected migration role restoration was incomplete")


