            "        EXECUTE format(\n                'REVOKE AL"
            "L PRIVILEGES ON FUNCTION dnd_generation_private.ca"
            "nonical_json(jsonb) FROM %I',\n                v_ru"
            "ntime_role\n            );\n            EXECUTE form"
            "at(\n                'REVOKE ALL PRIVILEGES ON FUNC"
            "TION dnd_generation_private.mutate(uuid, text, tex"
            "t, timestamptz, text, real, jsonb) FROM %I',\n     "
            "           v_runtime_role\n            );\n         "
            "   EXECUTE format(\n                'REVOKE ALL PRI"
            "VILEGES ON FUNCTION dnd_generation_admin.finalize_"
            "interface() FROM %I',\n                v_runtime_ro"
            "le\n            );\n            EXECUTE format(\n    "
            "            'REVOKE ALL PRIVILEGES ON FUNCTION dnd"
            "_generation_admin.install_interface() FROM %I',\n  "
