            "xt,timestamptz,text,real,jsonb)'::regprocedure,\n  "
            "      'EXECUTE'\n    ) OR NOT has_function_privileg"
            "e(\n        v_general_runtime_role,\n        'dnd_ge"
            "neration_private.mutate(uuid,text,text,timestamptz"
