            "      FROM pg_proc AS interface_function,\n        "
            "     LATERAL aclexplode(\n                 COALESCE"
            "(\n                     interface_function.proacl,\n"
            "                     acldefault('f', interface_fun"
            "ction.proowner)\n                 )\n             ) "
