            "ner, v_general_runtime_role, v_switchboard_runtime"
            "_role\n          )\n    ) OR EXISTS (\n        SELECT"
            " 1\n        FROM pg_proc AS interface_function,\n   "
            "          LATERAL aclexplode(\n                 COA"
            "LESCE(\n                     interface_function.pro"
            "acl,\n                     acldefault('f', interfac"
            "e_function.proowner)\n                 )\n          "
            "   ) AS acl\n        WHERE interface_function.oid ="
            "\n                  'dnd_generation_private.mutate("
            "uuid,text,text,timestamptz,text,real,jsonb)'::regp"
            "rocedure\n          AND acl.privilege_type = 'EXECU"
            "TE'\n          AND acl.grantee NOT IN (\n           "
            "   v_dnd_owner, v_general_runtime_role, v_switchbo"
            "ard_runtime_role\n          )\n    ) OR EXISTS (\n   "
            "     SELECT 1\n        FROM pg_namespace AS private"
            "_schema,\n             LATERAL aclexplode(\n        "
            "         COALESCE(private_schema.nspacl, acldefaul"
            "t('n', private_schema.nspowner))\n             ) AS"
            " acl\n        WHERE private_schema.nspname = 'dnd_g"
            "eneration_private'\n          AND acl.grantee NOT I"
            "N (\n              v_dnd_owner, v_general_runtime_r"
            "ole, v_switchboard_runtime_role\n          )\n    ) "
            "OR EXISTS (\n        SELECT 1\n        FROM pg_class"
            " AS audit_relation,\n             LATERAL aclexplod"
            "e(\n                 COALESCE(audit_relation.relacl"
            ", acldefault('r', audit_relation.relowner))\n      "
            "       ) AS acl\n        WHERE audit_relation.oid ="
            " 'public.dnd_generation_mutations'::regclass\n     "
            "     AND acl.grantee <> v_dnd_owner\n    ) OR EXIST"
            "S (\n        SELECT 1\n        FROM pg_namespace AS "
            "admin_schema,\n             LATERAL aclexplode(\n   "
            "              COALESCE(admin_schema.nspacl, acldef"
            "ault('n', admin_schema.nspowner))\n             ) A"
            "S acl\n        WHERE admin_schema.nspname = 'dnd_ge"
            "neration_admin'\n          AND acl.grantee <> v_boo"
            "tstrap_owner\n    ) OR EXISTS (\n        SELECT 1\n  "
            "      FROM pg_class AS configuration,\n            "
            " LATERAL aclexplode(\n                 COALESCE(con"
            "figuration.relacl, acldefault('r', configuration.r"
            "elowner))\n             ) AS acl\n        WHERE conf"
            "iguration.oid = 'dnd_generation_admin.bootstrap_co"
