            " attribute.attnum\n                   FROM pg_attri"
            "bute AS attribute\n                   WHERE attribu"
            "te.attrelid = 'public.user_context'::regclass\n    "
            "                 AND attribute.attname = 'id')\n   "
            "           ]::smallint[]\n       )\n       OR NOT EX"
            "ISTS (\n            SELECT 1\n            FROM pg_co"
            "nstraint AS constraint_row\n            WHERE const"
            "raint_row.conrelid = 'public.user_context'::regcla"
            "ss\n              AND constraint_row.contype = 'u'\n"
            "              AND constraint_row.conkey = ARRAY[\n "
            "                 (SELECT attribute.attnum\n        "
