            "           WHERE attribute.attrelid = 'public.user"
            "_context'::regclass\n                     AND attri"
            "bute.attname = 'signal_type'),\n                  ("
            "SELECT attribute.attnum\n                   FROM pg"
            "_attribute AS attribute\n                   WHERE a"
            "ttribute.attrelid = 'public.user_context'::regclas"
            "s\n                     AND attribute.attname = 'se"
            "t_by_butler')\n              ]::smallint[]\n       )"
            "\n       OR (SELECT count(*)\n           FROM pg_con"
            "straint AS constraint_row\n           WHERE constra"
            "int_row.conrelid = 'public.user_context'::regclass"
            ") <> 3\n       OR NOT EXISTS (\n            SELECT 1"
            "\n            FROM pg_constraint AS constraint_row\n"
            "            WHERE constraint_row.conrelid = 'publi"
            "c.user_context'::regclass\n              AND constr"
            "aint_row.conname = 'user_context_confidence_check'"
            "\n              AND constraint_row.contype = 'c'\n  "
            "     )\n       OR EXISTS (\n            SELECT 1\n   "
            "         FROM pg_depend AS dependency\n            "
