            ",\n        delivery_error_detail TEXT,\n        manu"
            "al_reissue_of UUID,\n        successor_id UUID\n    "
            ")\n    LANGUAGE plpgsql\n    SECURITY DEFINER\n    SE"
            "T search_path = pg_catalog, pg_temp\n    AS $observ"
            "e_runtime_attention_models$\n    BEGIN\n        IF C"
            "OALESCE(current_setting('role', true), 'none') <> "
            "'none' THEN\n            RAISE EXCEPTION 'runtime-a"
            "ttention operator observation forbids SET ROLE'\n  "
            "              USING ERRCODE = '42501';\n        END"
            " IF;\n        RETURN QUERY\n        SELECT DISTINCT "
            "ON (resolved.catalog_entry_id)\n            resolve"
            "d.catalog_entry_id,\n            resolved.episode_i"
            "d,\n            resolved.lifecycle_state,\n         "
            "   resolved.created_at,\n            resolved.updat"
            "ed_at,\n            resolved.delivered_at,\n        "
            "    resolved.delivery_error_class,\n            res"
            "olved.delivery_error_detail,\n            resolved."
            "manual_reissue_of,\n            child.id AS success"
