            "mary, daemon name, endpoint, or condition metadata"
            ".\n        DROP CONSTRAINT ck_runtime_attention_out"
            "box_snapshot_allowlist,\n        ADD CONSTRAINT ck_"
            "runtime_attention_outbox_snapshot_allowlist CHECK "
            "(\n            (manual_reissue_of IS NULL AND sourc"
            "e = 'model_breaker'\n                AND source_sna"
            "pshot ?& ARRAY[\n                    'catalog_entry"
            "_id', 'alias', 'model_id',\n                    'tr"
            "iggering_attempt_id', 'consecutive_failures'\n     "
            "           ]\n                AND source_snapshot -"
            " ARRAY[\n                    'catalog_entry_id', 'a"
            "lias', 'model_id',\n                    'triggering"
            "_attempt_id', 'consecutive_failures'\n             "
