            "    AND source_snapshot ?& ARRAY['month', 'denied_"
            "count', 'first_denied_at']\n                AND sou"
            "rce_snapshot - ARRAY['month', 'denied_count', 'fir"
            "st_denied_at']\n                    = '{}'::jsonb)\n"
            "            OR (manual_reissue_of IS NOT NULL AND "
            "source = 'model_breaker'\n                AND sourc"
            "e_snapshot ?& ARRAY[\n                    'catalog_"
            "entry_id', 'alias', 'model_id', 'triggering_attemp"
            "t_id',\n                    'consecutive_failures',"
            " 'reissue_of'\n                ]\n                AN"
            "D source_snapshot - ARRAY[\n                    'ca"
            "talog_entry_id', 'alias', 'model_id', 'triggering_"
            "attempt_id',\n                    'consecutive_fail"
            "ures', 'reissue_of'\n                ] = '{}'::json"
            "b)\n            OR (manual_reissue_of IS NULL AND s"
            "ource = 'control_plane_condition'\n                "
            "AND source_snapshot ?& ARRAY['condition_id', 'cond"
            "ition_kind', 'first_detected_at']\n                "
            "AND source_snapshot - ARRAY['condition_id', 'condi"
            "tion_kind', 'first_detected_at']\n                 "
            "   = '{}'::jsonb\n                AND source_snapsh"
            "ot->>'condition_kind' IN ('fleet_control', 'qa_pat"
            "rol_overdue'))\n        ),\n        DROP CONSTRAINT "
            "ck_runtime_attention_outbox_payload_allowlist,\n   "
            "     ADD CONSTRAINT ck_runtime_attention_outbox_pa"
            "yload_allowlist CHECK (\n            (manual_reissu"
            "e_of IS NULL AND source = 'model_breaker'\n        "
            "        AND payload ?& ARRAY['classification', 'co"
            "nsecutive_failures', 'door']\n                AND p"
            "ayload - ARRAY['classification', 'consecutive_fail"
            "ures', 'door']\n                    = '{}'::jsonb)\n"
            "            OR (manual_reissue_of IS NULL AND sour"
            "ce = 'fleet_halt'\n                AND payload ?& A"
            "RRAY['classification', 'door']\n                AND"
            " payload - ARRAY['classification', 'door'] = '{}':"
            ":jsonb)\n            OR (manual_reissue_of IS NOT N"
            "ULL AND source = 'model_breaker'\n                A"
            "ND payload ?& ARRAY['classification', 'consecutive"
            "_failures', 'door']\n                AND payload - "
            "ARRAY['classification', 'consecutive_failures', 'd"
            "oor']\n                    = '{}'::jsonb)\n         "
            "   OR (manual_reissue_of IS NULL AND source = 'con"
            "trol_plane_condition'\n                AND payload "
            "?& ARRAY['classification', 'door']\n               "
            " AND payload - ARRAY['classification', 'door'] = '"
            "{}'::jsonb\n                AND (payload->>'classif"
            "ication', payload->>'door') IN (\n                 "
            "   ('fleet_control_unhealthy', '/system'),\n       "
            "             ('qa_patrol_overdue', '/system')\n    "
            "            ))\n        );\n    CREATE UNIQUE INDEX "
            "IF NOT EXISTS ux_runtime_attention_outbox_control_"
            "plane_condition\n        ON public.runtime_attentio"
            "n_outbox ((source_snapshot->>'condition_id'))\n    "
            "    WHERE source = 'control_plane_condition' AND m"
            "anual_reissue_of IS NULL;\n\n    -- Both v4 definers"
            " resolve names with pg_catalog and pg_temp only, a"
            "nd\n    -- every relation below is schema-qualified"
            ".  The migration login can\n    -- CREATE in public"
            ", so a public search_path would let it plant a bet"
            "ter\n    -- overload (e.g. public.hashtextextended("
            "text, integer)) that then runs as\n    -- runtime_a"
            "ttention_outbox_owner.\n    CREATE OR REPLACE FUNCT"
            "ION public.append_runtime_attention_condition(p_co"
            "ndition_id UUID)\n    RETURNS UUID\n    LANGUAGE plp"
            "gsql\n    SECURITY DEFINER\n    SET search_path = pg"
            "_catalog, pg_temp\n    AS $append_runtime_attention"
            "_condition$\n    DECLARE\n        -- The producer-ow"
            "ned initial attention grace.  The observer cycles\n"
            "        -- every half TTL, so an append lands well"
            " inside the ten-minute bound\n        -- while a si"
            "ngle transient failing cycle cannot page the owner"
            ".\n        v_attention_grace CONSTANT INTERVAL := i"
            "nterval '5 minutes';\n        v_enabled BOOLEAN;\n  "
            "      v_marker public.runtime_attention_condition_"
            "episodes%ROWTYPE;\n        v_condition RECORD;\n    "
            "    v_kind TEXT;\n        v_episode_id UUID;\n      "
            "  v_state TEXT;\n    BEGIN\n        IF current_setti"
            "ng('role', true) IS DISTINCT FROM 'butler_switchbo"
            "ard_rw' THEN\n            RAISE EXCEPTION 'runtime-"
            "attention condition producer requires SET ROLE but"
            "ler_switchboard_rw'\n                USING ERRCODE "
            "= '42501';\n        END IF;\n        SELECT producer"
            "_enabled INTO v_enabled\n        FROM public.runtim"
            "e_attention_condition_control WHERE singleton;\n   "
            "     IF NOT COALESCE(v_enabled, false) THEN\n      "
            "      RETURN NULL;\n        END IF;\n\n        PERFOR"
            "M pg_advisory_xact_lock(\n            hashtextexten"
            "ded('runtime_attention_condition:' || p_condition_"
            "id::text, 0::bigint)\n        );\n        -- Emitted"
            " once, forever.  Only refresh the retained deliver"
            "y category\n        -- while the outbox row still e"
            "xists; never mint a successor.\n        SELECT * IN"
            "TO v_marker\n        FROM public.runtime_attention_"
            "condition_episodes\n        WHERE condition_id = p_"
            "condition_id;\n        IF FOUND THEN\n            SE"
            "LECT lifecycle_state INTO v_state\n            FROM"
            " public.runtime_attention_outbox WHERE id = v_mark"
            "er.episode_id;\n            IF v_state IS NOT NULL "
            "AND v_state IS DISTINCT FROM v_marker.last_deliver"
            "y_state THEN\n                UPDATE public.runtime"
            "_attention_condition_episodes\n                SET "
            "last_delivery_state = v_state, updated_at = now()\n"
            "                WHERE condition_id = p_condition_i"
            "d;\n            END IF;\n            RETURN v_marker"
            ".episode_id;\n        END IF;\n\n        SELECT sourc"
            "e, fingerprint, state, first_detected_at INTO v_co"
            "ndition\n        FROM public.infra_conditions WHERE"
            " id = p_condition_id;\n        IF NOT FOUND THEN\n  "
            "          RAISE EXCEPTION 'runtime-attention condi"
            "tion not found' USING ERRCODE = 'P0002';\n        E"
            "ND IF;\n        -- Fixed server-side identities (bu"
            "tlers.core.fleet_conditions).  The\n        -- stop"
            "ped-by-policy QA identity is an intentional hold, "
            "not a page.\n        v_kind := CASE\n            WHE"
            "N v_condition.source = 'control_plane_fleet'\n     "
            "        AND v_condition.fingerprint\n              "
            "   = '72d8afdcf22a218132518788e87ecc64113b4d45b076"
            "16a628b840f985f9e799'\n                THEN 'fleet_"
            "control'\n            WHEN v_condition.source = 'qa"
            "_patrol_assurance'\n             AND v_condition.fi"
            "ngerprint\n                 = 'd3273e18ff648f040725"
            "c226cbde2317c3a20a06b2f7355186bc7e43979fbff2'\n    "
