            "_condition.first_detected_at > clock_timestamp() -"
            " v_attention_grace THEN\n            RETURN NULL;\n "
            "       END IF;\n\n        INSERT INTO public.runtime"
            "_attention_outbox (source, source_snapshot, payloa"
            "d)\n        VALUES (\n            'control_plane_con"
            "dition',\n            jsonb_build_object(\n         "
            "       'condition_id', p_condition_id::text,\n     "
            "           'condition_kind', v_kind,\n             "
            "   'first_detected_at', v_condition.first_detected"
            "_at\n            ),\n            jsonb_build_object("
            "\n                'classification',\n               "
            " CASE v_kind\n                    WHEN 'fleet_contr"
            "ol' THEN 'fleet_control_unhealthy'\n               "
            "     ELSE 'qa_patrol_overdue'\n                END,"
