            "cle_state INTO v_episode_id, v_state;\n        IF v"
            "_episode_id IS NULL THEN\n            SELECT id, li"
            "fecycle_state INTO v_episode_id, v_state\n         "
            "   FROM public.runtime_attention_outbox\n          "
            "  WHERE source = 'control_plane_condition'\n       "
            "       AND manual_reissue_of IS NULL\n             "
            " AND source_snapshot->>'condition_id' = p_conditio"
            "n_id::text;\n        END IF;\n        INSERT INTO pu"
            "blic.runtime_attention_condition_episodes (\n      "
            "      condition_id, condition_kind, episode_id, la"
            "st_delivery_state\n        ) VALUES (p_condition_id"
