            "_temp';\n\n    EXECUTE 'ALTER TABLE public.runtime_a"
            "ttention_condition_episodes ENABLE ROW LEVEL SECUR"
            "ITY';\n    EXECUTE 'ALTER TABLE public.runtime_atte"
            "ntion_condition_episodes FORCE ROW LEVEL SECURITY'"
            ";\n    FOR v_policy_name IN\n        SELECT policy.p"
            "olname::name\n        FROM pg_policy AS policy\n    "
            "    WHERE policy.polrelid = 'public.runtime_attent"
            "ion_condition_episodes'::regclass\n    LOOP\n       "
            " EXECUTE format(\n            'DROP POLICY %I ON pu"
            "blic.runtime_attention_condition_episodes', v_poli"
            "cy_name\n        );\n    END LOOP;\n    EXECUTE 'CREA"
            "TE POLICY runtime_attention_condition_episodes_own"
            "er '\n        || 'ON public.runtime_attention_condi"
            "tion_episodes '\n        || 'FOR ALL TO runtime_att"
            "ention_outbox_owner USING (true) WITH CHECK (true)"
            "';\n\n    -- Only the no-login owner touches the mar"
            "ker and control rows directly;\n    -- only Switchb"
            "oard's role may append; only the migration login o"
            "bserves.\n    FOR v_acl_role IN\n        SELECT DIST"
            "INCT role_row.rolname::name\n        FROM pg_class "
            "AS relation\n        CROSS JOIN LATERAL aclexplode("
            "\n            COALESCE(relation.relacl, acldefault("
            "'r', relation.relowner))\n        ) AS acl\n        "
            "JOIN pg_roles AS role_row ON role_row.oid = acl.gr"
            "antee\n        WHERE relation.oid IN (\n            "
            "'public.runtime_attention_condition_control'::regc"
            "lass,\n            'public.runtime_attention_condit"
            "ion_episodes'::regclass\n        )\n          AND ro"
            "le_row.rolname <> 'runtime_attention_outbox_owner'"
            "\n    LOOP\n        EXECUTE format(\n            'REV"
            "OKE ALL PRIVILEGES ON TABLE public.runtime_attenti"
            "on_condition_control FROM %I',\n            v_acl_r"
            "ole\n        );\n        EXECUTE format(\n           "
            " 'REVOKE ALL PRIVILEGES ON TABLE public.runtime_at"
            "tention_condition_episodes FROM %I',\n            v"
            "_acl_role\n        );\n    END LOOP;\n    FOR v_acl_r"
            "ole IN\n        SELECT DISTINCT role_row.rolname::n"
            "ame\n        FROM pg_proc AS interface_function\n   "
            "     CROSS JOIN LATERAL aclexplode(\n            CO"
            "ALESCE(interface_function.proacl, acldefault('f', "
            "interface_function.proowner))\n        ) AS acl\n   "
            "     JOIN pg_roles AS role_row ON role_row.oid = a"
            "cl.grantee\n        WHERE interface_function.oid IN"
            " (\n            'public.append_runtime_attention_co"
            "ndition(uuid)'::regprocedure,\n            'public."
            "observe_runtime_attention_conditions()'::regproced"
            "ure,\n            'public.runtime_attention_upgrade"
            "_condition_v4()'::regprocedure\n        )\n         "
            " AND role_row.rolname <> 'runtime_attention_outbox"
            "_owner'\n    LOOP\n        EXECUTE format(\n         "
            "   'REVOKE ALL PRIVILEGES ON FUNCTION public.appen"
            "d_runtime_attention_condition(uuid) FROM %I',\n    "
            "        v_acl_role\n        );\n        EXECUTE form"
            "at(\n            'REVOKE ALL PRIVILEGES ON FUNCTION"
