            "le, v_interface_version\n    FROM runtime_attention"
            "_admin.bootstrap_configuration\n    WHERE singleton"
            ";\n    SELECT oid INTO v_outbox_owner\n    FROM pg_r"
            "oles\n    WHERE rolname = 'runtime_attention_outbox"
            "_owner';\n    SELECT nspowner INTO v_bootstrap_owne"
            "r\n    FROM pg_namespace\n    WHERE nspname = 'runti"
            "me_attention_admin';\n    IF v_migration_role IS NU"
            "LL OR v_bootstrap_role IS NULL OR v_outbox_owner I"
            "S NULL\n       OR v_bootstrap_owner IS NULL\n       "
            "OR NOT COALESCE((SELECT rolsuper FROM pg_roles WHE"
            "RE rolname = v_bootstrap_role), false) THEN\n      "
            "  RAISE EXCEPTION 'runtime-attention bootstrap con"
            "figuration is untrusted';\n    END IF;\n    IF to_re"
            "gclass('public.runtime_attention_outbox') IS NULL\n"
            "       OR to_regclass('public.runtime_attention_de"
            "livery_lease') IS NULL\n       OR to_regprocedure('"
            "public.append_runtime_attention_model_breaker(bigi"
            "nt)') IS NULL\n       OR to_regprocedure('public.ap"
            "pend_runtime_attention_fleet_halt()') IS NULL\n    "
            "   OR to_regprocedure('public.runtime_attention_ac"
            "tive_switchboard_role()') IS NULL\n       OR to_reg"
            "procedure('public.runtime_attention_outbox_guard()"
            "') IS NULL\n       OR to_regprocedure('public.runti"
            "me_attention_delivery_lease_guard()') IS NULL\n    "
            "   OR to_regprocedure('public.runtime_attention_up"
            "grade_operator_v3()') IS NULL\n       OR to_regproc"
            "edure('public.runtime_attention_deactivate_operato"
            "r_v3()') IS NULL\n       OR to_regprocedure('public"
            ".runtime_attention_upgrade_condition_v4()') IS NUL"
            "L\n       OR to_regprocedure('public.runtime_attent"
            "ion_deactivate_condition_v4()') IS NULL\n       OR "
            "to_regprocedure('public.runtime_attention_upgrade_"
            "condition_marker_v5()') IS NULL\n       OR to_regpr"
            "ocedure('public.runtime_attention_deactivate_condi"
            "tion_marker_v5()') IS NULL THEN\n        RAISE EXCE"
            "PTION 'runtime-attention interface is incomplete';"
            "\n    END IF;\n    IF EXISTS (\n        SELECT 1\n    "
            "    FROM pg_class AS relation\n        WHERE relati"
            "on.oid IN (\n            'public.runtime_attention_"
            "outbox'::regclass,\n            'public.runtime_att"
            "ention_delivery_lease'::regclass\n        )\n       "
            "   AND relation.relowner NOT IN (v_bootstrap_owner"
            ", v_outbox_owner)\n    ) OR EXISTS (\n        SELECT"
            " 1\n        FROM pg_proc AS interface_function\n    "
            "    WHERE interface_function.oid IN (\n            "
            "'public.append_runtime_attention_model_breaker(big"
            "int)'::regprocedure,\n            'public.append_ru"
            "ntime_attention_fleet_halt()'::regprocedure,\n     "
            "       'public.runtime_attention_active_switchboar"
            "d_role()'::regprocedure,\n            'public.runti"
            "me_attention_outbox_guard()'::regprocedure,\n      "
            "      'public.runtime_attention_delivery_lease_gua"
            "rd()'::regprocedure,\n            'public.runtime_a"
            "ttention_upgrade_operator_v3()'::regprocedure,\n   "
            "         'public.runtime_attention_deactivate_oper"
            "ator_v3()'::regprocedure,\n            'public.runt"
            "ime_attention_upgrade_condition_v4()'::regprocedur"
            "e,\n            'public.runtime_attention_deactivat"
            "e_condition_v4()'::regprocedure,\n            'publ"
            "ic.runtime_attention_upgrade_condition_marker_v5()"
            "'::regprocedure,\n            'public.runtime_atten"
            "tion_deactivate_condition_marker_v5()'::regprocedu"
            "re\n        )\n          AND interface_function.proo"
            "wner NOT IN (v_bootstrap_owner, v_outbox_owner)\n  "
            "  ) THEN\n        RAISE EXCEPTION 'runtime-attentio"
            "n interface ownership is untrusted';\n    END IF;\n\n"
            "    -- The dedicated owner is deliberately a no-lo"
            "gin, membership-free role;\n    -- no shared migrat"
            "ion/runtime login owns a SECURITY DEFINER function"
            ".\n    EXECUTE 'ALTER TABLE public.runtime_attentio"
            "n_outbox OWNER TO runtime_attention_outbox_owner';"
            "\n    EXECUTE 'ALTER TABLE public.runtime_attention"
            "_delivery_lease OWNER TO runtime_attention_outbox_"
            "owner';\n    EXECUTE 'ALTER FUNCTION public.append_"
            "runtime_attention_model_breaker(bigint) OWNER TO r"
            "untime_attention_outbox_owner';\n    EXECUTE 'ALTER"
            " FUNCTION public.append_runtime_attention_fleet_ha"
            "lt() OWNER TO runtime_attention_outbox_owner';\n   "
            " EXECUTE 'ALTER FUNCTION public.runtime_attention_"
            "active_switchboard_role() OWNER TO runtime_attenti"
            "on_outbox_owner';\n    EXECUTE 'ALTER FUNCTION publ"
            "ic.runtime_attention_outbox_guard() OWNER TO runti"
            "me_attention_outbox_owner';\n    EXECUTE 'ALTER FUN"
            "CTION public.runtime_attention_delivery_lease_guar"
            "d() OWNER TO runtime_attention_outbox_owner';\n    "
            "-- The v3 upgrader is bootstrap-owned until its on"
            "e-shot migration has\n    -- created the operator c"
            "ontrol table.  Moving it earlier would make its\n  "
            "  -- DDL execute with the least-privilege outbox o"
            "wner.  The deactivator only\n    -- updates the out"
            "box-owned control table and can be fenced immediat"
            "ely.\n    EXECUTE 'ALTER FUNCTION public.runtime_at"
            "tention_deactivate_operator_v3() OWNER TO runtime_"
            "attention_outbox_owner';\n    IF to_regclass('publi"
            "c.runtime_attention_operator_control') IS NOT NULL"
            " THEN\n        EXECUTE 'ALTER TABLE public.runtime_"
            "attention_operator_control OWNER TO runtime_attent"
            "ion_outbox_owner';\n        EXECUTE 'ALTER FUNCTION"
            " public.runtime_attention_upgrade_operator_v3() OW"
            "NER TO runtime_attention_outbox_owner';\n    END IF"
            ";\n    -- The v4 condition upgrader follows the sam"
            "e bootstrap-owned-until-used\n    -- rule; its inst"
            "alled objects are re-fenced on every rerun.\n    EX"
            "ECUTE 'ALTER FUNCTION public.runtime_attention_dea"
            "ctivate_condition_v4() OWNER TO runtime_attention_"
            "outbox_owner';\n    EXECUTE 'ALTER FUNCTION public."
            "runtime_attention_deactivate_condition_marker_v5()"
            " OWNER TO runtime_attention_outbox_owner';\n    IF "
            "to_regclass('public.runtime_attention_condition_co"
            "ntrol') IS NOT NULL THEN\n        PERFORM runtime_a"
            "ttention_admin.finalize_condition_v4(v_migration_r"
            "ole);\n    END IF;\n    -- bu-mms5xl: every runtime-"
            "attention definer resolves names in pg_catalog\n   "
            " -- and pg_temp only.  The migration login can CRE"
            "ATE in public, so a\n    -- public entry would let "
            "it plant a better-matching overload (e.g.\n    -- p"
            "ublic.hashtextextended(text, integer)) that then r"
            "uns as\n    -- runtime_attention_outbox_owner.  Bod"
            "ies schema-qualify every relation.\n    -- The v3 o"
            "perator functions are created once by their upgrad"
            "er, so the\n    -- pin on an already-upgraded datab"
            "ase lands here.\n    IF to_regprocedure('public.rei"
            "ssue_runtime_attention_episode(uuid)') IS NOT NULL"
            " THEN\n        EXECUTE 'ALTER FUNCTION public.obser"
            "ve_runtime_attention_models() SET search_path = pg"
            "_catalog, pg_temp';\n        EXECUTE 'ALTER FUNCTIO"
            "N public.observe_runtime_attention_fleet_halt() SE"
            "T search_path = pg_catalog, pg_temp';\n        EXEC"
            "UTE 'ALTER FUNCTION public.reissue_runtime_attenti"
            "on_episode(uuid) SET search_path = pg_catalog, pg_"
            "temp';\n    END IF;\n    EXECUTE 'ALTER FUNCTION pub"
            "lic.append_runtime_attention_model_breaker(bigint)"
            " SET search_path = pg_catalog, pg_temp';\n    EXECU"
            "TE 'ALTER FUNCTION public.append_runtime_attention"
            "_fleet_halt() SET search_path = pg_catalog, pg_tem"
            "p';\n    EXECUTE 'ALTER FUNCTION public.runtime_att"
            "ention_active_switchboard_role() SET search_path ="
            " pg_catalog, pg_temp';\n    EXECUTE 'ALTER FUNCTION"
            " public.runtime_attention_outbox_guard() SET searc"
            "h_path = pg_catalog, pg_temp';\n    EXECUTE 'ALTER "
            "FUNCTION public.runtime_attention_delivery_lease_g"
            "uard() SET search_path = pg_catalog, pg_temp';\n\n  "
            "  EXECUTE 'ALTER TABLE public.runtime_attention_ou"
            "tbox ENABLE ROW LEVEL SECURITY';\n    EXECUTE 'ALTE"
            "R TABLE public.runtime_attention_outbox FORCE ROW "
            "LEVEL SECURITY';\n    EXECUTE 'ALTER TABLE public.r"
            "untime_attention_delivery_lease ENABLE ROW LEVEL S"
            "ECURITY';\n    EXECUTE 'ALTER TABLE public.runtime_"
            "attention_delivery_lease FORCE ROW LEVEL SECURITY'"
            ";\n\n    -- RLS policies compose permissively.  Remo"
            "ve every non-system policy\n    -- before restoring"
            " the two fixed policies so an ad-hoc broad policy\n"
            "    -- cannot survive an init-db rerun beside the "
            "active-role gate.\n    FOR v_policy_name IN\n       "
            " SELECT policy.polname::name\n        FROM pg_polic"
            "y AS policy\n        WHERE policy.polrelid = 'publi"
            "c.runtime_attention_outbox'::regclass\n    LOOP\n   "
            "     EXECUTE format(\n            'DROP POLICY %I O"
            "N public.runtime_attention_outbox', v_policy_name\n"
            "        );\n    END LOOP;\n    EXECUTE 'CREATE POLIC"
            "Y runtime_attention_outbox_owner ON public.runtime"
            "_attention_outbox '\n        || 'FOR ALL TO runtime"
            "_attention_outbox_owner USING (true) WITH CHECK (t"
            "rue)';\n    EXECUTE 'CREATE POLICY runtime_attentio"
            "n_outbox_switchboard ON public.runtime_attention_o"
            "utbox '\n        || 'FOR ALL TO butler_switchboard_"
            "rw '\n        || 'USING (public.runtime_attention_a"
            "ctive_switchboard_role()) '\n        || 'WITH CHECK"
            " (public.runtime_attention_active_switchboard_role"
            "())';\n\n    FOR v_policy_name IN\n        SELECT pol"
            "icy.polname::name\n        FROM pg_policy AS policy"
            "\n        WHERE policy.polrelid = 'public.runtime_a"
            "ttention_delivery_lease'::regclass\n    LOOP\n      "
            "  EXECUTE format(\n            'DROP POLICY %I ON p"
            "ublic.runtime_attention_delivery_lease', v_policy_"
            "name\n        );\n    END LOOP;\n    EXECUTE 'CREATE "
            "POLICY runtime_attention_delivery_lease_owner ON p"
            "ublic.runtime_attention_delivery_lease '\n        |"
            "| 'FOR ALL TO runtime_attention_outbox_owner USING"
            " (true) WITH CHECK (true)';\n    EXECUTE 'CREATE PO"
            "LICY runtime_attention_delivery_lease_switchboard "
            "ON public.runtime_attention_delivery_lease '\n     "
            "   || 'FOR ALL TO butler_switchboard_rw '\n        "
            "|| 'USING (public.runtime_attention_active_switchb"
            "oard_role()) '\n        || 'WITH CHECK (public.runt"
            "ime_attention_active_switchboard_role())';\n\n    --"
            " The trigger guards are as authority-bearing as th"
            "e RLS policies.  Keep\n    -- the relations to exac"
            "tly the bootstrap-defined guards on every rerun.\n "
            "   FOR v_trigger_name IN\n        SELECT trigger_ro"
            "w.tgname::name\n        FROM pg_trigger AS trigger_"
            "row\n        WHERE trigger_row.tgrelid = 'public.ru"
            "ntime_attention_outbox'::regclass\n          AND NO"
            "T trigger_row.tgisinternal\n    LOOP\n        EXECUT"
            "E format(\n            'DROP TRIGGER %I ON public.r"
            "untime_attention_outbox', v_trigger_name\n        )"
            ";\n    END LOOP;\n    FOR v_trigger_name IN\n        "
            "SELECT trigger_row.tgname::name\n        FROM pg_tr"
            "igger AS trigger_row\n        WHERE trigger_row.tgr"
            "elid = 'public.runtime_attention_delivery_lease'::"
            "regclass\n          AND NOT trigger_row.tgisinterna"
            "l\n    LOOP\n        EXECUTE format(\n            'DR"
            "OP TRIGGER %I ON public.runtime_attention_delivery"
            "_lease', v_trigger_name\n        );\n    END LOOP;\n "
            "   EXECUTE 'CREATE TRIGGER runtime_attention_outbo"
            "x_guard_trigger '\n        || 'BEFORE UPDATE ON pub"
            "lic.runtime_attention_outbox '\n        || 'FOR EAC"
            "H ROW EXECUTE FUNCTION public.runtime_attention_ou"
            "tbox_guard()';\n    EXECUTE 'CREATE TRIGGER runtime"
            "_attention_delivery_lease_guard_trigger '\n        "
            "|| 'BEFORE INSERT OR UPDATE ON public.runtime_atte"
            "ntion_delivery_lease '\n        || 'FOR EACH ROW EX"
            "ECUTE FUNCTION public.runtime_attention_delivery_l"
            "ease_guard()';\n    -- The v5 condition-marker sync"
            " is the one other bootstrap-defined outbox\n    -- "
            "trigger; restore it (and re-fence its definer) onl"
            "y while installed.\n    IF to_regprocedure('public."
            "runtime_attention_sync_condition_marker()') IS NOT"
            " NULL THEN\n        PERFORM runtime_attention_admin"
            ".finalize_condition_marker_v5();\n    END IF;\n\n    "
            "EXECUTE 'REVOKE ALL PRIVILEGES ON SCHEMA public FR"
            "OM runtime_attention_outbox_owner';\n    EXECUTE 'G"
            "RANT USAGE ON SCHEMA public TO runtime_attention_o"
            "utbox_owner';\n    EXECUTE 'REVOKE ALL PRIVILEGES O"
            "N TABLE public.model_catalog FROM runtime_attentio"
            "n_outbox_owner';\n    EXECUTE 'REVOKE ALL PRIVILEGE"
            "S ON TABLE public.model_dispatch_attempts FROM run"
            "time_attention_outbox_owner';\n    EXECUTE 'GRANT S"
            "ELECT ON TABLE public.model_catalog TO runtime_att"
            "ention_outbox_owner';\n    EXECUTE 'GRANT SELECT ON"
            " TABLE public.model_dispatch_attempts TO runtime_a"
            "ttention_outbox_owner';\n\n    EXECUTE 'REVOKE ALL P"
            "RIVILEGES ON TABLE public.runtime_attention_outbox"
            " FROM PUBLIC';\n    EXECUTE 'REVOKE ALL PRIVILEGES "
            "ON TABLE public.runtime_attention_delivery_lease F"
            "ROM PUBLIC';\n    EXECUTE 'REVOKE ALL PRIVILEGES ON"
            " FUNCTION public.append_runtime_attention_model_br"
            "eaker(bigint) FROM PUBLIC';\n    EXECUTE 'REVOKE AL"
            "L PRIVILEGES ON FUNCTION public.append_runtime_att"
            "ention_fleet_halt() FROM PUBLIC';\n    EXECUTE 'REV"
            "OKE ALL PRIVILEGES ON FUNCTION public.runtime_atte"
            "ntion_active_switchboard_role() FROM PUBLIC';\n    "
            "EXECUTE 'REVOKE ALL PRIVILEGES ON FUNCTION public."
            "runtime_attention_outbox_guard() FROM PUBLIC';\n   "
            " EXECUTE 'REVOKE ALL PRIVILEGES ON FUNCTION public"
            ".runtime_attention_delivery_lease_guard() FROM PUB"
            "LIC';\n    EXECUTE 'REVOKE ALL PRIVILEGES ON FUNCTI"
            "ON public.runtime_attention_upgrade_operator_v3() "
            "FROM PUBLIC';\n    EXECUTE 'REVOKE ALL PRIVILEGES O"
            "N FUNCTION public.runtime_attention_deactivate_ope"
            "rator_v3() FROM PUBLIC';\n    EXECUTE 'REVOKE ALL P"
            "RIVILEGES ON FUNCTION public.runtime_attention_upg"
            "rade_condition_marker_v5() FROM PUBLIC';\n    EXECU"
            "TE 'REVOKE ALL PRIVILEGES ON FUNCTION public.runti"
            "me_attention_deactivate_condition_marker_v5() FROM"
            " PUBLIC';\n    EXECUTE 'REVOKE ALL PRIVILEGES ON SC"
            "HEMA runtime_attention_admin FROM PUBLIC';\n    EXE"
            "CUTE 'REVOKE ALL PRIVILEGES ON TABLE runtime_atten"
            "tion_admin.bootstrap_configuration FROM PUBLIC';\n\n"
            "    -- Remove stale direct grants to unlisted role"
            "s as well as the known\n    -- init-db grants below"
            ".  A later bootstrap must not preserve an ad-hoc\n "
            "   -- principal merely because it was absent from "
            "the historical role list.\n    FOR v_acl_role IN\n  "
            "      SELECT DISTINCT role_row.rolname::name\n     "
            "   FROM pg_proc AS interface_function\n        CROS"
            "S JOIN LATERAL aclexplode(\n            COALESCE(in"
            "terface_function.proacl, acldefault('f', interface"
            "_function.proowner))\n        ) AS acl\n        JOIN"
            " pg_roles AS role_row ON role_row.oid = acl.grante"
            "e\n        WHERE interface_function.oid IN (\n      "
            "      'public.append_runtime_attention_model_break"
            "er(bigint)'::regprocedure,\n            'public.app"
            "end_runtime_attention_fleet_halt()'::regprocedure\n"
            "        )\n          AND acl.privilege_type = 'EXEC"
            "UTE'\n          AND role_row.rolname <> ALL (ARRAY["
            "\n              'runtime_attention_outbox_owner',\n "
            "             'butler_chronicler_rw', 'butler_conci"
            "erge_rw', 'butler_education_rw',\n              'bu"
            "tler_finance_rw', 'butler_general_rw', 'butler_hea"
            "lth_rw', 'butler_home_rw',\n              'butler_l"
            "ifestyle_rw', 'butler_messenger_rw', 'butler_qa_rw"
            "',\n              'butler_relationship_rw', 'butler"
            "_switchboard_rw', 'butler_travel_rw'\n          ]::"
            "name[])\n    LOOP\n        EXECUTE format(\n         "
            "   'REVOKE ALL PRIVILEGES ON FUNCTION public.appen"
            "d_runtime_attention_model_breaker(bigint) FROM %I'"
            ",\n            v_acl_role\n        );\n        EXECUT"
            "E format(\n            'REVOKE ALL PRIVILEGES ON FU"
            "NCTION public.append_runtime_attention_fleet_halt("
            ") FROM %I',\n            v_acl_role\n        );\n    "
            "END LOOP;\n    FOR v_acl_role IN\n        SELECT DIS"
            "TINCT role_row.rolname::name\n        FROM pg_class"
            " AS relation\n        CROSS JOIN LATERAL aclexplode"
            "(\n            COALESCE(relation.relacl, acldefault"
            "('r', relation.relowner))\n        ) AS acl\n       "
            " JOIN pg_roles AS role_row ON role_row.oid = acl.g"
            "rantee\n        WHERE relation.oid IN (\n           "
            " 'public.runtime_attention_outbox'::regclass,\n    "
            "        'public.runtime_attention_delivery_lease':"
            ":regclass\n        )\n          AND role_row.rolname"
            " <> ALL (ARRAY[\n              'runtime_attention_o"
            "utbox_owner', 'butler_switchboard_rw'\n          ]:"
            ":name[])\n    LOOP\n        EXECUTE format(\n        "
            "    'REVOKE ALL PRIVILEGES ON TABLE public.runtime"
            "_attention_outbox FROM %I', v_acl_role\n        );\n"
            "        EXECUTE format(\n            'REVOKE ALL PR"
            "IVILEGES ON TABLE public.runtime_attention_deliver"
            "y_lease FROM %I',\n            v_acl_role\n        )"
            ";\n    END LOOP;\n\n    -- Revoke the broad init-db g"
            "rants from every reachable shared identity,\n    --"
            " then grant the two intentionally disjoint interfa"
            "ces back.  The SET\n    -- ROLE gates in the functi"
            "ons/policies make inherited membership alone\n    -"
            "- insufficient proof of a producer or Switchboard "
            "identity.\n    FOREACH v_runtime_role IN ARRAY ARRA"
            "Y[\n        'butler_chronicler_rw',\n        'butler"
            "_concierge_rw',\n        'butler_education_rw',\n   "
            "     'butler_finance_rw',\n        'butler_general_"
            "rw',\n        'butler_health_rw',\n        'butler_h"
            "ome_rw',\n        'butler_lifestyle_rw',\n        'b"
            "utler_messenger_rw',\n        'butler_qa_rw',\n     "
            "   'butler_relationship_rw',\n        'butler_switc"
            "hboard_rw',\n        'butler_travel_rw',\n        'c"
            "onnector_writer'\n    ]::name[] LOOP\n        IF EXI"
            "STS (SELECT 1 FROM pg_roles WHERE rolname = v_runt"
            "ime_role) THEN\n            EXECUTE format('REVOKE "
            "ALL PRIVILEGES ON TABLE public.runtime_attention_o"
            "utbox FROM %I', v_runtime_role);\n            EXECU"
            "TE format('REVOKE ALL PRIVILEGES ON TABLE public.r"
            "untime_attention_delivery_lease FROM %I', v_runtim"
            "e_role);\n            EXECUTE format('REVOKE ALL PR"
            "IVILEGES ON FUNCTION public.append_runtime_attenti"
            "on_model_breaker(bigint) FROM %I', v_runtime_role)"
            ";\n            EXECUTE format('REVOKE ALL PRIVILEGE"
            "S ON FUNCTION public.append_runtime_attention_flee"
            "t_halt() FROM %I', v_runtime_role);\n            EX"
            "ECUTE format('REVOKE ALL PRIVILEGES ON FUNCTION pu"
            "blic.runtime_attention_active_switchboard_role() F"
            "ROM %I', v_runtime_role);\n            EXECUTE form"
            "at('REVOKE ALL PRIVILEGES ON FUNCTION public.runti"
            "me_attention_outbox_guard() FROM %I', v_runtime_ro"
            "le);\n            EXECUTE format('REVOKE ALL PRIVIL"
            "EGES ON FUNCTION public.runtime_attention_delivery"
            "_lease_guard() FROM %I', v_runtime_role);\n        "
            "END IF;\n    END LOOP;\n    EXECUTE format('REVOKE A"
            "LL PRIVILEGES ON TABLE public.runtime_attention_ou"
            "tbox FROM %I', v_migration_role);\n    EXECUTE form"
            "at('REVOKE ALL PRIVILEGES ON TABLE public.runtime_"
            "attention_delivery_lease FROM %I', v_migration_rol"
            "e);\n    EXECUTE format('REVOKE ALL PRIVILEGES ON F"
            "UNCTION public.append_runtime_attention_model_brea"
            "ker(bigint) FROM %I', v_migration_role);\n    EXECU"
            "TE format('REVOKE ALL PRIVILEGES ON FUNCTION publi"
            "c.append_runtime_attention_fleet_halt() FROM %I', "
            "v_migration_role);\n    EXECUTE format('REVOKE ALL "
            "PRIVILEGES ON FUNCTION public.runtime_attention_ac"
            "tive_switchboard_role() FROM %I', v_migration_role"
            ");\n    EXECUTE format('REVOKE ALL PRIVILEGES ON FU"
            "NCTION public.runtime_attention_outbox_guard() FRO"
            "M %I', v_migration_role);\n    EXECUTE format('REVO"
            "KE ALL PRIVILEGES ON FUNCTION public.runtime_atten"
            "tion_delivery_lease_guard() FROM %I', v_migration_"
            "role);\n    EXECUTE format('REVOKE ALL PRIVILEGES O"
            "N SCHEMA runtime_attention_admin FROM %I', v_migra"
            "tion_role);\n    EXECUTE format('REVOKE ALL PRIVILE"
            "GES ON TABLE runtime_attention_admin.bootstrap_con"
            "figuration FROM %I', v_migration_role);\n    -- The"
            " migration login is handed the installer only whil"
            "e the boundary is\n    -- wholly absent.  Once inst"
            "alled, it keeps no access to the admin control\n   "
            " -- functions; later core-schema runs prove the fi"
            "nalized catalog and no-op.\n    EXECUTE format('REV"
            "OKE ALL PRIVILEGES ON FUNCTION runtime_attention_a"
            "dmin.finalize_interface() FROM %I', v_migration_ro"
            "le);\n    EXECUTE format('REVOKE ALL PRIVILEGES ON "
            "FUNCTION runtime_attention_admin.install_interface"
            "() FROM %I', v_migration_role);\n    EXECUTE format"
            "('REVOKE ALL PRIVILEGES ON FUNCTION runtime_attent"
            "ion_admin.rollback_interface() FROM %I', v_migrati"
            "on_role);\n\n    FOREACH v_runtime_role IN ARRAY ARR"
            "AY[\n        'butler_chronicler_rw',\n        'butle"
            "r_concierge_rw',\n        'butler_education_rw',\n  "
            "      'butler_finance_rw',\n        'butler_general"
            "_rw',\n        'butler_health_rw',\n        'butler_"
            "home_rw',\n        'butler_lifestyle_rw',\n        '"
            "butler_messenger_rw',\n        'butler_qa_rw',\n    "
            "    'butler_relationship_rw',\n        'butler_swit"
            "chboard_rw',\n        'butler_travel_rw'\n    ]::nam"
            "e[] LOOP\n        IF NOT EXISTS (SELECT 1 FROM pg_r"
            "oles WHERE rolname = v_runtime_role) THEN\n        "
            "    RAISE EXCEPTION 'runtime-attention producer ro"
            "le % is missing', v_runtime_role;\n        END IF;\n"
            "        EXECUTE format(\n            'GRANT EXECUTE"
            " ON FUNCTION public.append_runtime_attention_model"
            "_breaker(bigint) TO %I',\n            v_runtime_rol"
            "e\n        );\n        EXECUTE format(\n            '"
            "GRANT EXECUTE ON FUNCTION public.append_runtime_at"
            "tention_fleet_halt() TO %I',\n            v_runtime"
            "_role\n        );\n    END LOOP;\n\n    -- The deliver"
            "y worker is activated (roster/switchboard/modules/"
            "__init__.py\n    -- constructs and schedules it at "
            "startup), so the REQ-database-security-007\n    -- "
            "carve-out that kept the finite terminal-error voca"
            "bulary and the optional\n    -- notification refere"
            "nce ungranted no longer applies: Switchboard needs"
            "\n    -- write access to record a proven terminal o"
            "utcome. The\n    -- ck_runtime_attention_outbox_del"
            "ivery_evidence CHECK constraint remains the\n    --"
            " enforcement boundary -- only the fixed non-secret"
            "\n    -- (delivery_error_class, delivery_error_deta"
            "il) pairs are accepted, and\n    -- notification_re"
            "f stays a plain scalar UUID with no cross-schema F"
            "K.\n    EXECUTE 'GRANT SELECT, UPDATE (lifecycle_st"
            "ate, claim_token, claim_epoch, delivery_lease_epoc"
            "h, claimed_by_instance, claimed_at, claim_expires_"
            "at, next_attempt_at, delivered_at, delivery_error_"
            "class, delivery_error_detail, notification_ref) '\n"
            "        || 'ON TABLE public.runtime_attention_outb"
            "ox TO butler_switchboard_rw';\n    EXECUTE 'GRANT S"
            "ELECT, INSERT, UPDATE ON TABLE public.runtime_atte"
            "ntion_delivery_lease TO butler_switchboard_rw';\n  "
            "  EXECUTE 'GRANT EXECUTE ON FUNCTION public.runtim"
            "e_attention_active_switchboard_role() TO butler_sw"
            "itchboard_rw';\n\n    -- Only the dedicated definer "
            "can make an immutable source snapshot; it is\n    -"
            "- not a generic payload sink.  Reassert the post-f"
            "inalization shape on\n    -- every init-db rerun so"
            " broad legacy grants cannot survive bootstrap.\n   "
            " IF EXISTS (\n        SELECT 1\n        FROM aclexpl"
            "ode(\n            COALESCE(\n                (SELECT"
            " relacl FROM pg_class WHERE oid = 'public.runtime_"
            "attention_outbox'::regclass),\n                acld"
            "efault('r', v_outbox_owner)\n            )\n        "
            ") AS acl\n        WHERE acl.grantee = 0\n          A"
            "ND acl.privilege_type IN ('SELECT', 'INSERT', 'UPD"
            "ATE', 'DELETE')\n    ) THEN\n        RAISE EXCEPTION"
            " 'runtime-attention outbox PUBLIC DML ACL repair f"
            "ailed';\n    END IF;\n    EXECUTE 'ALTER DEFAULT PRI"
            "VILEGES FOR ROLE runtime_attention_outbox_owner '\n"
            "        || 'IN SCHEMA public REVOKE ALL ON TABLES "
            "FROM PUBLIC';\n    EXECUTE 'ALTER DEFAULT PRIVILEGE"
            "S FOR ROLE runtime_attention_outbox_owner '\n      "
            "  || 'IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS"
            " FROM PUBLIC';\n\n    IF v_interface_version = 1 THE"
            "N\n        -- core_198 installs the inert v1 bounda"
            "ry.  Preserve exactly one\n        -- short-lived p"
            "ath for the immediately following core_199 migrati"
            "on;\n        -- upgrade_producers_v2 revokes this g"
            "rant before it returns.\n        EXECUTE format('GR"
            "ANT USAGE ON SCHEMA runtime_attention_admin TO %I'"
            ", v_migration_role);\n        EXECUTE format(\n     "
            "       'GRANT EXECUTE ON FUNCTION runtime_attentio"
            "n_admin.upgrade_producers_v2() TO %I',\n           "
            " v_migration_role\n        );\n    ELSIF v_interface"
            "_version = 2 THEN\n        EXECUTE 'ALTER TABLE pub"
            "lic.runtime_attention_producer_control '\n         "
            "   || 'OWNER TO runtime_attention_outbox_owner';\n "
            "       EXECUTE 'REVOKE ALL PRIVILEGES ON TABLE '\n "
            "           || 'public.runtime_attention_producer_c"
            "ontrol FROM PUBLIC';\n        FOREACH v_runtime_rol"
            "e IN ARRAY ARRAY[\n            'butler_chronicler_r"
            "w', 'butler_concierge_rw', 'butler_education_rw',\n"
            "            'butler_finance_rw', 'butler_general_r"
            "w', 'butler_health_rw', 'butler_home_rw',\n        "
            "    'butler_lifestyle_rw', 'butler_messenger_rw', "
            "'butler_qa_rw', 'butler_relationship_rw',\n        "
            "    'butler_switchboard_rw', 'butler_travel_rw',\n "
            "           'connector_writer'\n        ]::name[] LO"
            "OP\n            IF EXISTS (SELECT 1 FROM pg_roles W"
            "HERE rolname = v_runtime_role) THEN\n              "
            "  EXECUTE format(\n                    'REVOKE ALL "
            "PRIVILEGES ON TABLE '\n                    || 'publ"
            "ic.runtime_attention_producer_control FROM %I',\n  "
            "                  v_runtime_role\n                )"
            ";\n            END IF;\n        END LOOP;\n        EX"
            "ECUTE format(\n            'REVOKE ALL PRIVILEGES O"
            "N TABLE '\n            || 'public.runtime_attention"
            "_producer_control FROM %I',\n            v_migratio"
            "n_role\n        );\n        -- bu-kww1r renamed the "
            "marker planter.  Its body lives in\n        -- upgr"
            "ade_producers_v2, which does not re-run once a dat"
            "abase is at v2,\n        -- so adopt the new name h"
            "ere: ALTER ... RENAME preserves the OID, which\n   "
            "     -- is what the trigger binds to, so this is a"
            " pure rename and the marker\n        -- keeps plant"
            "ing across it.  Without this the ALTERs below woul"
            'd raise\n        -- "function does not exist" on ev'
            "ery rerun of an existing v2 database.\n        -- T"
            "he rename alone leaves the stored body untouched; "
            "the adoption\n        -- below refreshes it, which "
            "is what converges the audit literals.\n        IF t"
            "o_regprocedure('public.runtime_attention_plant_leg"
            "acy_debounce_marker()') IS NULL\n           AND to_"
            "regprocedure('public.runtime_attention_legacy_prod"
