_RETIRED_ADMIN_SCHEMAS = (
    "dnd_generation_admin",
    "runtime_attention_admin",
    "restore_drill_executor_admin",
)


def classify_retired_interfaces(observed, maintenance_actor: str):
    """Only exact pinned predecessors can be retired; discovery adds no DDL."""
    from .roles import AuthorityError

    expected = {(r[0], r[1], r[2]): r for r in _RETIRED_PREDECESSOR_FUNCTIONS}
    seen = set()
    accepted = []
    for row in observed:
        key = row["schema"], row["name"], row["signature"].replace(", ", ",")
        source = expected.get(key)
        if source is None or key in seen:
            raise AuthorityError("Predecessor interface population is not source-owned")
        seen.add(key)
        if row["digest"] != source[3] or row["owner"] != (source[4] or maintenance_actor):
            raise AuthorityError("Predecessor interface provenance is unavailable")
        accepted.append(source)
    return tuple(accepted)


def inspect_retired_interfaces(connection, migration_owner: str):
    """Read-only whole-population preflight before any retirement effects.

    The three singleton rows are deployment configuration, not user/evidence
    data. Their known owner and selected normal-role binding must be proved.
    No unknown table, function, sequence or populated namespace is adopted.
    """
    from sqlalchemy import text

    from .apply import quote_identifier
    from .roles import AuthorityError

    require_maintenance(connection)
    actor = connection.exec_driver_sql("SELECT session_user").scalar_one()
    rows = tuple(
        connection.execute(
            text("""
        SELECT n.nspname AS schema, p.proname AS name,
          replace(pg_catalog.oidvectortypes(p.proargtypes),', ', ',') AS signature,
          owner.rolname AS owner,
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p.prosrc,'UTF8')),'hex')
            AS digest
        FROM pg_catalog.pg_proc p
        JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
        JOIN pg_catalog.pg_roles owner ON owner.oid=p.proowner
        WHERE n.nspname=ANY(:schemas) OR (n.nspname='public' AND
          (p.proname LIKE 'runtime_attention_upgrade_%'
           OR p.proname LIKE 'runtime_attention_deactivate_%'
           OR p.proname='runtime_attention_plant_legacy_debounce_marker'))
    """),
            {"schemas": list(_RETIRED_ADMIN_SCHEMAS)},
        ).mappings()
    )
    definitions = classify_retired_interfaces(rows, actor)
    namespaces = tuple(
        connection.execute(
            text("""
        SELECT n.nspname AS name, owner.rolname AS owner
        FROM pg_catalog.pg_namespace n JOIN pg_catalog.pg_roles owner ON owner.oid=n.nspowner
        WHERE n.nspname=ANY(:schemas)
    """),
            {"schemas": list(_RETIRED_ADMIN_SCHEMAS)},
        ).mappings()
    )
    for namespace in namespaces:
        schema = namespace["name"]
        if namespace["owner"] != actor:
            raise AuthorityError("Predecessor namespace ownership prerequisite is unavailable")
        objects = tuple(
            connection.execute(
                text("""
            SELECT c.relname AS name, c.relkind AS kind, owner.rolname AS owner
            FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
            JOIN pg_catalog.pg_roles owner ON owner.oid=c.relowner
            WHERE n.nspname=:schema AND c.relkind NOT IN ('i','I','t')
        """),
                {"schema": schema},
            ).mappings()
        )
        if len(objects) != 1 or dict(objects[0]) != dict(
            name="bootstrap_configuration", kind="r", owner=actor
        ):
            raise AuthorityError("Predecessor singleton population is unavailable")
        expected_columns = [
            ("singleton", "boolean", True),
            ("migration_role", "name", True),
            ("bootstrap_role", "name", True),
        ]
        if schema == "runtime_attention_admin":
            expected_columns += [
                ("interface_version", "integer", True),
                ("producers_enabled", "boolean", True),
                ("producer_activated_at", "timestamp with time zone", False),
            ]
        columns = connection.execute(
            text("""
            SELECT a.attname, pg_catalog.format_type(a.atttypid,a.atttypmod), a.attnotnull
            FROM pg_catalog.pg_attribute a
            WHERE a.attrelid=pg_catalog.to_regclass(:relation)
              AND a.attnum>0 AND NOT a.attisdropped ORDER BY a.attnum
        """),
            {"relation": schema + ".bootstrap_configuration"},
        ).all()
        if columns != expected_columns:
            raise AuthorityError("Predecessor singleton columns are not source-owned")
        configuration = connection.exec_driver_sql(
            f"SELECT singleton, migration_role::text, bootstrap_role::text "
            f"FROM {quote_identifier(schema)}.bootstrap_configuration"
        ).all()
        if configuration != [(True, migration_owner, actor)]:
            raise AuthorityError("Predecessor singleton binding is unavailable")
    # Only the obsolete compatibility marker trigger is removed. Its exact
    # relation/type/function/condition are preconditions, not name assumptions.
    triggers = tuple(
        connection.exec_driver_sql("""
        SELECT t.tgname, n.nspname, c.relname, fnn.nspname, p.proname,
               t.tgtype, t.tgisinternal, t.tgqual IS NULL,
               t.tgenabled, t.tgnargs, t.tgattr::text,
               pg_catalog.encode(t.tgargs,'hex'), t.tgconstraint,
               t.tgdeferrable, t.tginitdeferred, t.tgparentid
        FROM pg_catalog.pg_trigger t
        JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid
        JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
        JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid
        JOIN pg_catalog.pg_namespace fnn ON fnn.oid=p.pronamespace
        WHERE p.proname='runtime_attention_plant_legacy_debounce_marker'
    """).all()
    )
    if triggers and triggers != (
        (
            "runtime_attention_plant_legacy_debounce_marker_trigger",
            "public",
            "model_dispatch_attempts",
            "public",
            "runtime_attention_plant_legacy_debounce_marker",
            7,
            False,
            True,
            "O",
            0,
            "",
            "",
            0,
            False,
            False,
            0,
        ),
    ):
        raise AuthorityError("Predecessor compatibility trigger is not source-owned")
    return definitions, tuple(row["name"] for row in namespaces), bool(triggers)


def retire_predecessor_interfaces(connection, prepared) -> None:
    """Apply a previously validated fixed retirement without CASCADE/data reset.

    Called only after final protected functions have converged, so their bodies
    no longer depend on the administrative predecessor projection gateway. A
    remaining dependency refuses this transaction; it is never cascade-erased.
    """
    from .apply import quote_identifier

    definitions, namespaces, has_marker = prepared
    if has_marker:
        connection.exec_driver_sql(
            "DROP TRIGGER runtime_attention_plant_legacy_debounce_marker_trigger "
            "ON public.model_dispatch_attempts"
        )
    for schema, name, signature, *_ in definitions:
        connection.exec_driver_sql(
            f"DROP FUNCTION {quote_identifier(schema)}."
            f"{quote_identifier(name)}({signature}) RESTRICT"
        )
    for schema in namespaces:
        target = quote_identifier(schema)
        connection.exec_driver_sql(f"DROP TABLE {target}.bootstrap_configuration RESTRICT")
        connection.exec_driver_sql(f"DROP SCHEMA {target} RESTRICT")


