            "st be in [0, 1]';\n        END IF;\n\n        SELECT "
            "guard.generation INTO v_guard_generation\n        F"
            "ROM public.dnd_generation_guard AS guard\n        W"
            "HERE guard.guard_id = 1\n        FOR UPDATE;\n      "
            "  IF v_guard_generation IS NULL OR v_guard_generat"
            "ion < 0 THEN\n            RAISE EXCEPTION 'DND gene"
            "ration guard is missing or invalid';\n        END I"
            "F;\n\n        SELECT * INTO v_existing\n        FROM "
            "public.dnd_generation_mutations AS receipt\n       "
            " WHERE receipt.mutation_id = p_mutation_id;\n      "
            "  v_has_existing := FOUND;\n\n        IF v_has_exist"
            "ing THEN\n            IF v_existing.semantic_finger"
            "print_version <> 1\n               OR v_existing.se"
            "mantic_fingerprint IS NULL\n               OR (v_ex"
            "isting.operation = 'set' AND v_existing.effective_"
            "expires_at IS NULL)\n               OR (v_existing."
            "operation = 'clear'\n                   AND (v_exis"
            "ting.requested_expires_at IS NOT NULL\n            "
            "            OR v_existing.effective_expires_at IS "
            "NOT NULL)) THEN\n                RAISE EXCEPTION 'r"
            "eplay_identity_unprovable';\n            END IF;\n  "
            "          v_effective_expires_at := v_existing.eff"
