            "y_canonical := CASE\n            WHEN v_effective_e"
            "xpires_at IS NULL THEN NULL\n            ELSE to_ch"
            "ar(\n                v_effective_expires_at AT TIME"
            " ZONE 'UTC',\n                'YYYY-MM-DD\"T\"HH24:MI"
            ':SS.US"Z"\'\n            )\n        END;\n        v_co'
            "nfidence_canonical := CASE\n            WHEN p_conf"
            "idence IS NULL THEN NULL\n            ELSE encode(f"
            "loat4send(p_confidence), 'hex')\n        END;\n     "
            "   v_value_normalized := CASE\n            WHEN p_v"
            'alue IS NULL THEN NULL\n            ELSE "normalize'
            "\"(p_value, 'NFC')\n        END;\n        v_value_dig"
            "est := CASE\n            WHEN v_value_normalized IS"
            " NULL THEN encode(\n                sha256(convert_"
            "to('dnd-value:null', 'UTF8')), 'hex'\n            )"
            "\n            ELSE encode(\n                sha256(\n"
            "                    convert_to('dnd-value:string:'"
            " || v_value_normalized, 'UTF8')\n                ),"
            "\n                'hex'\n            )\n        END;\n"
            "        v_metadata_digest := encode(\n            s"
            "ha256(\n                convert_to(\n               "
