            "\n            'hex'\n        );\n        v_fingerprin"
            "t := encode(\n            sha256(\n                c"
            "onvert_to(\n                    dnd_generation_priv"
            "ate.canonical_json(\n                        jsonb_"
            "build_object(\n                            'protoco"
            "l', 'context.dnd.mutate.v1',\n                     "
            "       'signal_type', 'dnd',\n                     "
            "       'writer', v_effective_writer,\n             "
            "               'set_by_butler', v_effective_writer"
