            "tion,\n                            'correlation', v"
            "_correlation,\n                            'request"
            "ed_expires_at', v_requested_expiry_canonical,\n    "
            "                        'effective_expires_at', v_"
            "effective_expiry_canonical,\n                      "
            "      'confidence_float4', v_confidence_canonical,"
            "\n                            'value_digest', v_val"
            "ue_digest,\n                            'metadata_d"
            "igest', v_metadata_digest\n                        "
            ")\n                    ),\n                    'UTF8"
            "'\n                )\n            ),\n            'he"
            "x'\n        );\n\n        IF v_has_existing THEN\n    "
            "        IF v_existing.writer IS DISTINCT FROM v_ef"
            "fective_writer\n               OR v_existing.operat"
            "ion IS DISTINCT FROM p_operation\n               OR"
            " v_existing.correlation IS DISTINCT FROM v_correla"
            "tion\n               OR v_existing.semantic_fingerp"
            "rint IS DISTINCT FROM v_fingerprint THEN\n         "
            "       RAISE EXCEPTION 'idempotency_conflict';\n   "
            "         END IF;\n            RETURN QUERY\n        "
            "    SELECT v_existing.mutation_id, v_existing.gene"
            "ration, v_existing.writer,\n                   v_ex"
            "isting.operation, v_existing.correlation,\n        "
            "           v_existing.requested_expires_at, v_exis"
            "ting.effective_expires_at,\n                   v_ex"
            "isting.committed_at;\n            RETURN;\n        E"
            "ND IF;\n\n        IF v_guard_generation = 9223372036"
            "854775807 THEN\n            RAISE EXCEPTION 'DND ge"
            "neration is exhausted';\n        END IF;\n        IF"
            " v_now IS NULL THEN\n            v_now := clock_tim"
            "estamp();\n        END IF;\n\n        IF p_operation "
            "= 'set' THEN\n            INSERT INTO public.user_c"
            "ontext (\n                id, signal_type, value, s"
            "et_by_butler, set_at, expires_at, confidence,\n    "
            "            metadata, superseded_at\n            )\n"
            "            VALUES (\n                gen_random_uu"
            "id(), 'dnd', p_value, v_effective_writer, v_now, v"
            "_effective_expires_at,\n                p_confidenc"
            "e, p_metadata, NULL\n            )\n            ON C"
            "ONFLICT (signal_type, set_by_butler) DO UPDATE\n   "
            "             SET value = EXCLUDED.value,\n         "
            "           set_at = EXCLUDED.set_at,\n             "
            "       expires_at = EXCLUDED.expires_at,\n         "
            "           confidence = EXCLUDED.confidence,\n     "
            "               metadata = EXCLUDED.metadata,\n     "
            "               superseded_at = NULL;\n        ELSE\n"
            "            UPDATE public.user_context\n           "
            " SET superseded_at = v_now\n            WHERE signa"
            "l_type = 'dnd'\n              AND set_by_butler = v"
            "_effective_writer\n              AND superseded_at "
            "IS NULL;\n        END IF;\n\n        UPDATE public.dn"
            "d_generation_guard AS guard\n        SET generation"
            " = guard.generation + 1,\n            updated_at = "
            "v_now\n        WHERE guard.guard_id = 1\n        RET"
            "URNING guard.generation INTO v_guard_generation;\n\n"
            "        INSERT INTO public.dnd_generation_mutation"
            "s (\n            mutation_id, generation, writer, o"
            "peration, correlation,\n            requested_expir"
            "es_at, effective_expires_at,\n            semantic_"
            "fingerprint_version, semantic_fingerprint, committ"
            "ed_at\n        )\n        VALUES (\n            p_mut"
            "ation_id, v_guard_generation, v_effective_writer, "
            "p_operation,\n            v_correlation, p_requeste"
            "d_expires_at, v_effective_expires_at,\n            "
