            "lass\n              AND attribute.attname = 'value'"
            "\n              AND attribute.atttypid = 'text'::re"
            "gtype\n              AND NOT attribute.attnotnull\n "
            "      )\n       OR NOT EXISTS (\n            SELECT "
            "1\n            FROM pg_attribute AS attribute\n     "
            "       WHERE attribute.attrelid = 'public.user_con"
            "text'::regclass\n              AND attribute.attnam"
            "e = 'set_by_butler'\n              AND attribute.at"
            "ttypid = 'text'::regtype\n              AND attribu"
            "te.attnotnull\n       )\n       OR NOT EXISTS (\n    "
            "        SELECT 1\n            FROM pg_attribute AS "
            "attribute\n            WHERE attribute.attrelid = '"
            "public.user_context'::regclass\n              AND a"
            "ttribute.attname = 'set_at'\n              AND attr"
            "ibute.atttypid = 'timestamptz'::regtype\n          "
            "    AND attribute.attnotnull\n       )\n       OR NO"
            "T EXISTS (\n            SELECT 1\n            FROM p"
            "g_attribute AS attribute\n            WHERE attribu"
            "te.attrelid = 'public.user_context'::regclass\n    "
            "          AND attribute.attname = 'expires_at'\n   "
            "           AND attribute.atttypid = 'timestamptz':"
            ":regtype\n              AND attribute.attnotnull\n  "
            "     )\n       OR NOT EXISTS (\n            SELECT 1"
            "\n            FROM pg_attribute AS attribute\n      "
            "      WHERE attribute.attrelid = 'public.user_cont"
            "ext'::regclass\n              AND attribute.attname"
            " = 'confidence'\n              AND attribute.atttyp"
            "id = 'real'::regtype\n              AND attribute.a"
            "ttnotnull\n       )\n       OR NOT EXISTS (\n        "
            "    SELECT 1\n            FROM pg_attribute AS attr"
            "ibute\n            WHERE attribute.attrelid = 'publ"
            "ic.user_context'::regclass\n              AND attri"
            "bute.attname = 'metadata'\n              AND attrib"
            "ute.atttypid = 'jsonb'::regtype\n              AND "
            "NOT attribute.attnotnull\n       )\n       OR NOT EX"
            "ISTS (\n            SELECT 1\n            FROM pg_at"
            "tribute AS attribute\n            WHERE attribute.a"
            "ttrelid = 'public.user_context'::regclass\n        "
            "      AND attribute.attname = 'superseded_at'\n    "
            "          AND attribute.atttypid = 'timestamptz'::"
            "regtype\n              AND NOT attribute.attnotnull"
            "\n       )\n       OR NOT EXISTS (\n            SELEC"
            "T 1\n            FROM pg_constraint AS constraint_r"
            "ow\n            WHERE constraint_row.conrelid = 'pu"
            "blic.user_context'::regclass\n              AND con"
            "straint_row.contype = 'p'\n              AND constr"
            "aint_row.conkey = ARRAY[\n                  (SELECT"
            " attribute.attnum\n                   FROM pg_attri"
            "bute AS attribute\n                   WHERE attribu"
            "te.attrelid = 'public.user_context'::regclass\n    "
            "                 AND attribute.attname = 'id')\n   "
