            "            WHERE constraint_row.conrelid = 'publi"
            "c.user_context'::regclass\n              AND constr"
            "aint_row.conname = 'user_context_confidence_check'"
            "\n              AND constraint_row.contype = 'c'\n  "
            "     )\n       OR EXISTS (\n            SELECT 1\n   "
            "         FROM pg_depend AS dependency\n            "
            "JOIN pg_proc AS referenced_function ON referenced_"
            "function.oid = dependency.refobjid\n            JOI"
            "N pg_namespace AS function_schema\n                "
            "ON function_schema.oid = referenced_function.prona"
            "mespace\n            JOIN pg_constraint AS constrai"
            "nt_row ON constraint_row.oid = dependency.objid\n  "
            "          WHERE dependency.classid = 'pg_constrain"
            "t'::regclass\n              AND dependency.refclass"
            "id = 'pg_proc'::regclass\n              AND constra"
            "int_row.conrelid = 'public.user_context'::regclass"
            "\n              AND function_schema.nspname <> 'pg_"
            "catalog'\n       )\n       OR EXISTS (\n            S"
            "ELECT 1\n            FROM pg_depend AS dependency\n "
            "           JOIN pg_operator AS referenced_operator"
            " ON referenced_operator.oid = dependency.refobjid\n"
            "            JOIN pg_namespace AS operator_schema\n "
