            "               SELECT attribute.attnum\n           "
            "       FROM pg_attribute AS attribute\n            "
            "      WHERE attribute.attrelid = 'public.user_cont"
            "ext'::regclass\n                    AND attribute.a"
            "ttname = 'signal_type'\n              )\n           "
