            "ULL)'\n       )\n       OR EXISTS (\n            SELE"
            "CT 1\n            FROM pg_rewrite AS rewrite_rule\n "
            "           WHERE rewrite_rule.ev_class = 'public.u"
            "ser_context'::regclass\n              AND rewrite_r"
            "ule.rulename <> '_RETURN'\n       ) THEN\n        RA"
            "ISE EXCEPTION 'DND generation requires the canonic"
            "al user_context shape';\n    END IF;\n\n    EXECUTE f"
            "ormat('ALTER TABLE public.user_context OWNER TO %I"
            "', v_bootstrap_owner);\n    CREATE SCHEMA dnd_gener"
            "ation_private AUTHORIZATION dnd_generation_owner;\n"
            "    -- Create it under the bootstrap owner first s"
            "o finalizer provenance is\n    -- explicit; the fin"
            "al ownership handoff happens only after full catal"
            "og\n    -- and ACL proof.\n    EXECUTE format('ALTER"
            " SCHEMA dnd_generation_private OWNER TO %I', v_boo"
            "tstrap_owner);\n\n    CREATE TABLE public.dnd_genera"
            "tion_guard (\n        guard_id SMALLINT PRIMARY KEY"
            " DEFAULT 1 CHECK (guard_id = 1),\n        generatio"
            "n BIGINT NOT NULL DEFAULT 0 CHECK (generation >= 0"
            "),\n        updated_at TIMESTAMPTZ NOT NULL DEFAULT"
            " clock_timestamp()\n    );\n    INSERT INTO public.d"
            "nd_generation_guard (guard_id, generation)\n    VAL"
            "UES (1, 0);\n\n    CREATE TABLE public.dnd_generatio"
            "n_mutations (\n        mutation_id UUID PRIMARY KEY"
            ",\n        generation BIGINT NOT NULL CHECK (genera"
            "tion >= 0),\n        writer TEXT NOT NULL CHECK (wr"
            "iter IN ('general', 'switchboard')),\n        opera"
