            "xt_select ON public.user_context\n        FOR SELEC"
            "T TO PUBLIC USING (true);\n    CREATE POLICY dnd_us"
            "er_context_insert ON public.user_context\n        F"
            "OR INSERT TO PUBLIC\n        WITH CHECK (signal_typ"
            "e <> 'dnd' OR current_user = 'dnd_generation_owner"
