            "ublic.user_context\n        FOR UPDATE TO PUBLIC\n  "
            "      USING (signal_type <> 'dnd' OR current_user "
            "= 'dnd_generation_owner')\n        WITH CHECK (sign"
            "al_type <> 'dnd' OR current_user = 'dnd_generation"
            "_owner');\n    CREATE POLICY dnd_user_context_delet"
            "e ON public.user_context\n        FOR DELETE TO PUB"
            "LIC\n        USING (signal_type <> 'dnd' OR current"
            "_user = 'dnd_generation_owner');\n\n    CREATE FUNCT"
            "ION dnd_generation_private.canonical_json(p_docume"
            "nt JSONB)\n    RETURNS TEXT\n    LANGUAGE plpgsql\n  "
            "  IMMUTABLE\n    SECURITY INVOKER\n    SET search_pa"
            "th = pg_catalog, pg_temp\n    AS $dnd_canonical_jso"
            "n$\n    DECLARE\n        v_kind TEXT;\n        v_rend"
            "ered TEXT;\n    BEGIN\n        IF p_document IS NULL"
            " THEN\n            RETURN 'null';\n        END IF;\n\n"
            "        v_kind := jsonb_typeof(p_document);\n      "
            "  IF v_kind = 'object' THEN\n            -- JSONB g"
            "ives deterministic structural semantics, while thi"
            "s\n            -- explicit rendering also normalize"
            "s Unicode object keys. A pair\n            -- of di"
            "stinct source keys that normalizes to the same NFC"
            " key is\n            -- ambiguous for replay identi"
            "ty and must fail closed.\n            IF EXISTS (\n "
            "               SELECT 1\n                FROM (\n   "
            '                 SELECT "normalize"(entry.key, \'NF'
            "C') AS normalized_key\n                    FROM jso"
            "nb_each(p_document) AS entry\n                ) AS "
            "normalized_keys\n                GROUP BY normalize"
            "d_key\n                HAVING count(*) > 1\n        "
            "    ) THEN\n                RAISE EXCEPTION 'DND me"
            "tadata has duplicate NFC-normalized keys';\n       "
            "     END IF;\n\n            SELECT '{' || string_agg"
            '(\n                to_jsonb("normalize"(entry.key, '
            "'NFC'))::text\n                || ':' || dnd_genera"
            "tion_private.canonical_json(entry.value),\n        "
            "        ',' ORDER BY convert_to(\"normalize\"(entry."
            "key, 'NFC'), 'UTF8')\n            ) || '}'\n        "
            "    INTO v_rendered\n            FROM jsonb_each(p_"
            "document) AS entry;\n            RETURN COALESCE(v_"
            "rendered, '{}');\n        ELSIF v_kind = 'array' TH"
            "EN\n            SELECT '[' || string_agg(\n         "
            "       dnd_generation_private.canonical_json(entry"
            ".value),\n                ',' ORDER BY entry.ordina"
            "lity\n            ) || ']'\n            INTO v_rende"
            "red\n            FROM jsonb_array_elements(p_docume"
            "nt) WITH ORDINALITY AS entry(value, ordinality);\n "
            "           RETURN COALESCE(v_rendered, '[]');\n    "
            "    ELSIF v_kind = 'string' THEN\n            RETUR"
            "N to_jsonb(\"normalize\"(p_document #>> '{}', 'NFC')"
            ")::text;\n        ELSIF v_kind = 'number' THEN\n    "
            "        -- JSONB rejects non-JSON numeric input, b"
            "ut keep the canonical\n            -- form explicit"
            ": numeric display scale must not make 1, 1.0, and\n"
            "            -- 1.00 distinct replay identities. Po"
            "stgreSQL numeric NaN is not\n            -- a valid"
            " JSON number and is rejected defensively if encoun"
            "tered.\n            IF (p_document #>> '{}')::numer"
            "ic = 'NaN'::numeric THEN\n                RAISE EXC"
            "EPTION 'DND metadata numeric value is not finite';"
            "\n            END IF;\n            RETURN trim_scale"
            "((p_document #>> '{}')::numeric)::text;\n        EN"
            "D IF;\n\n        -- JSONB renders scalar booleans an"
            "d null deterministically.\n        RETURN p_documen"
            "t::text;\n    END;\n    $dnd_canonical_json$;\n\n    -"
            "- The private mutation body is defined once, in\n  "
            "  -- dnd_generation_admin.install_private_mutation"
            ", which finalize_interface\n    -- re-adopts on eve"
            "ry init-db rerun.\n    PERFORM dnd_generation_admin"
            ".install_private_mutation();\n\n    CREATE FUNCTION "
            "public.context_dnd_mutate(\n        p_mutation_id U"
