            "o_regprocedure('public.runtime_attention_plant_leg"
            "acy_debounce_marker()') IS NULL\n           AND to_"
            "regprocedure('public.runtime_attention_legacy_prod"
            "ucer_fence()') IS NOT NULL\n        THEN\n          "
            "  EXECUTE 'ALTER FUNCTION public.runtime_attention"
            "_legacy_producer_fence() '\n                || 'REN"
            "AME TO runtime_attention_plant_legacy_debounce_mar"
            "ker';\n        END IF;\n        IF EXISTS (\n        "
            "    SELECT 1 FROM pg_trigger\n            WHERE tgr"
            "elid = 'public.model_dispatch_attempts'::regclass\n"
            "              AND tgname = 'runtime_attention_lega"
            "cy_producer_fence_trigger'\n              AND NOT t"
            "gisinternal\n        ) THEN\n            EXECUTE 'AL"
            "TER TRIGGER runtime_attention_legacy_producer_fenc"
            "e_trigger '\n                || 'ON public.model_di"
            "spatch_attempts '\n                || 'RENAME TO ru"
