            "SERT INTO public.runtime_attention_outbox (\n      "
            "      source, triggering_attempt_id, source_snapsh"
            "ot, payload\n        )\n        VALUES (\n           "
            " 'model_breaker',\n            p_triggering_attempt"
            "_id,\n            jsonb_build_object(\n             "
            "   'catalog_entry_id', v_catalog_entry_id::text,\n "
            "               'alias', v_alias,\n                '"
            "model_id', v_model_id,\n                'triggering"
            "_attempt_id', p_triggering_attempt_id,\n           "
            "     'consecutive_failures', 5\n            ),\n    "
            "        jsonb_build_object(\n                'class"
            "ification', 'model_breaker_open',\n                "
            "'consecutive_failures', 5,\n                'door',"
            " '/settings/models?highlight=' || v_catalog_entry_"
            "id::text\n            )\n        )\n        ON CONFLI"
            "CT (triggering_attempt_id)\n            WHERE sourc"
            "e = 'model_breaker' AND triggering_attempt_id IS N"
            "OT NULL\n            DO NOTHING\n        RETURNING i"
            "d INTO v_episode_id;\n        IF v_episode_id IS NU"
            "LL THEN\n            SELECT id INTO v_episode_id\n  "
            "          FROM public.runtime_attention_outbox\n   "
            "         WHERE source = 'model_breaker'\n          "
            "    AND triggering_attempt_id = p_triggering_attem"
            "pt_id;\n        END IF;\n        RETURN v_episode_id"
            ";\n    END;\n    $runtime_attention_model_breaker_v2"
            "$;\n\n    -- The v2 fleet-halt producer's body is de"
            "fined once, in\n    -- runtime_attention_admin.inst"
            "all_fleet_halt_producer_v2, so that this\n    -- on"
