            "();\n\n    DROP TRIGGER IF EXISTS runtime_attention_"
            "legacy_producer_fence_trigger\n        ON public.mo"
            "del_dispatch_attempts;\n    DROP TRIGGER IF EXISTS "
            "runtime_attention_plant_legacy_debounce_marker_tri"
            "gger\n        ON public.model_dispatch_attempts;\n  "
            "  CREATE TRIGGER runtime_attention_plant_legacy_de"
            "bounce_marker_trigger\n        BEFORE INSERT ON pub"
            "lic.model_dispatch_attempts\n        FOR EACH ROW\n "
            "       EXECUTE FUNCTION public.runtime_attention_p"
            "lant_legacy_debounce_marker();\n\n    UPDATE runtime"
            "_attention_admin.bootstrap_configuration\n    SET i"
            "nterface_version = 2,\n        producers_enabled = "
