            '.expires_at<=t THEN RETURN \'{"error":"AUTH_RESTART'
            "_REQUIRED\"}'; END IF;\n IF action='snapshot' THEN\n "
            " RETURN jsonb_build_object('ceremony',to_jsonb(q),"
            "'credential',to_jsonb(k));\n END IF;\n IF NOT p ?& A"
