            "ntial_id' IS DISTINCT FROM k.credential_id\n  OR (p"
            "->>'backup_eligible')::boolean IS DISTINCT FROM k."
            "backup_eligible\n  OR ((p->>'backup_state')::boolea"
            "n AND NOT k.backup_eligible)\n  OR (p->>'counter'):"
            ":bigint<0\n  OR (NOT k.backup_eligible AND (k.count"
            "er>0 OR (p->>'counter')::bigint>0)\n      AND (p->>"
            "'counter')::bigint<=k.counter)\n  OR p->>'nonce_dig"
            "est' !~ '^[0-9a-f]{64}$' THEN RETURN '{\"error\":\"UN"
