            "p->>'nonce_digest' WHERE id=b.id;\n RETURN jsonb_bu"
            "ild_object('expires_at',b.expires_at);\nEND $ceremo"
            "ny$;\nALTER FUNCTION dashboard_stepup.ceremony(text"
            ",jsonb) OWNER TO dashboard_stepup_owner;\nREVOKE AL"
            "L ON FUNCTION dashboard_stepup.ceremony(text,jsonb"
            ") FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION dashboard"
            "_stepup.ceremony(text,jsonb) TO dashboard_auth_api"
            ";\n\nCREATE FUNCTION dashboard_stepup.consume(\n phas"
            "e text,raw_nonce text,session_digest text,kind tex"
            "t,target text,\n request_digest text,action_digest "
            "text,result jsonb\n) RETURNS jsonb LANGUAGE plpgsql"
            " SECURITY DEFINER SET search_path=pg_catalog,pg_te"
            "mp AS $consume$\nDECLARE s dashboard_auth.instance%"
            "ROWTYPE; se dashboard_auth.sessions%ROWTYPE;\n b da"
            "shboard_stepup.bindings%ROWTYPE; t timestamptz;\nBE"
            "GIN\n -- A stored hash is never bearer authority. O"
