            ";\n SELECT * INTO s FROM dashboard_auth.instance WH"
            "ERE singleton FOR SHARE;\n t := clock_timestamp();\n"
            " IF NOT FOUND OR s.state<>'keyless_enrolled' OR s."
            'key_generation IS NOT NULL\n  THEN RETURN \'{"state"'
            ':"refused"}\'; END IF;\n SELECT * INTO se FROM dashb'
            "oard_auth.sessions x WHERE x.digest=consume.sessio"
            "n_digest;\n IF NOT FOUND OR se.revoked OR se.expire"
            "s_at<=t OR se.credential_epoch<>s.credential_epoch"
            "\n  OR se.session_epoch<>s.session_epoch THEN RETUR"
            'N \'{"state":"refused"}\'; END IF;\n SELECT * INTO b '
            "FROM dashboard_stepup.bindings x\n  WHERE x.nonce_d"
            "igest=encode(sha256(convert_to(raw_nonce,'UTF8')),"
            "'hex') FOR UPDATE;\n t := clock_timestamp();\n IF NO"
            "T FOUND OR b.session_digest<>se.digest OR b.revoke"
            "d OR se.expires_at<=t\n  OR b.credential_epoch<>s.c"
            "redential_epoch OR b.session_epoch<>s.session_epoc"
            "h\n  OR b.kind IS DISTINCT FROM kind OR b.target IS"
            " DISTINCT FROM target\n  OR b.request_digest IS DIS"
            'TINCT FROM request_digest THEN RETURN \'{"state":"r'
            "efused\"}'; END IF;\n -- Own successful source-state"
            " changes do not hide the immutable receipt.\n -- No"
            " new transition occurs on this path, even if the n"
            "once has since expired.\n IF phase='begin' AND b.re"
            "sult IS NOT NULL THEN\n  RETURN jsonb_build_object("
            "'state','completed','result',b.result);\n END IF;\n "
            "IF b.expires_at<=t OR b.action_digest IS DISTINCT "
            'FROM action_digest\n  THEN RETURN \'{"state":"refuse'
            "d\"}'; END IF;\n IF phase='begin' THEN\n  IF b.consum"
            'ed_at IS NOT NULL THEN RETURN \'{"state":"refused"}'
            "'; END IF;\n  UPDATE dashboard_stepup.bindings SET "
            "consumed_at=t,consumed_tx=txid_current() WHERE id="
