    (
        "public",
        "uuid_generate_v7",
        "",
        (
            "CREATE OR REPLACE FUNCTION public.uuid_generate_v7"
            "()\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\n"
        ),
        (
            "\nDECLARE\n    unix_ts_ms bytea;\n    uuid_bytes byte"
            "a;\nBEGIN\n    -- 48-bit big-endian Unix timestamp i"
            "n milliseconds (drop the 2 high zero\n    -- bytes "
            "of the 8-byte int8send output).\n    unix_ts_ms := "
            "substring(\n        int8send(floor(extract(epoch FR"
            "OM clock_timestamp()) * 1000)::bigint)\n        FRO"
            "M 3\n    );\n\n    -- Start from a random v4 UUID; it"
            "s byte 8 already carries the RFC-4122\n    -- varia"
            "nt bits (10xx) that UUIDv7 also requires.\n    uuid"
            "_bytes := uuid_send(gen_random_uuid());\n\n    -- Ov"
            "erlay the 6 timestamp bytes into the leading posit"
            "ions.\n    uuid_bytes := overlay(uuid_bytes PLACING"
            " unix_ts_ms FROM 1 FOR 6);\n\n    -- Force the versi"
            "on nibble (high 4 bits of byte 6) to 0111 = 7, kee"
            "p the\n    -- low nibble random.\n    uuid_bytes := "
            "set_byte(uuid_bytes, 6, (get_byte(uuid_bytes, 6) &"
            " 15) | 112);\n\n    RETURN encode(uuid_bytes, 'hex')"
            "::uuid;\nEND;\n"
        ),
    ),
