            "ncel_confirmed_at,\n    v_turn.terminal_state,\n    "
            "v_turn.terminal_at;\nRETURN;\n\n            END IF;\n\n"
            "            SELECT * INTO v_turn\n            FROM "
            "public.dashboard_conversation_turns\n            WH"
            "ERE message_id = p_message_id\n            FOR UPDA"
            "TE;\n            IF NOT FOUND THEN\n                "
            "\nRETURN QUERY SELECT\n    'missing'::text,\n    NULL"
            "::uuid,\n    NULL::uuid,\n    NULL::uuid,\n    NULL::"
            "text,\n    NULL::text,\n    NULL::uuid,\n    NULL::ti"
            "mestamptz,\n    NULL::timestamptz,\n    NULL::text,\n"
            "    NULL::timestamptz;\nRETURN;\n\n            END IF"
            ";\n            IF v_turn.conversation_id <> p_conve"
            "rsation_id THEN\n                p_outcome := 'conf"
            "lict';\n                \nRETURN QUERY SELECT\n    p_"
            "outcome,\n    v_turn.message_id,\n    v_turn.convers"
            "ation_id,\n    v_turn.request_id,\n    v_turn.target"
            "_butler,\n    v_turn.target_kind,\n    v_turn.route_"
            "inbox_id,\n    v_turn.cancel_requested_at,\n    v_tu"
            "rn.cancel_confirmed_at,\n    v_turn.terminal_state,"
            "\n    v_turn.terminal_at;\nRETURN;\n\n            END "
            "IF;\n            IF v_turn.terminal_at IS NOT NULL "
            "THEN\n                p_outcome := CASE\n           "
