        "public",
        "dashboard_turn_complete_session",
        "uuid,uuid,boolean",
        (
            "CREATE OR REPLACE FUNCTION public.dashboard_turn_c"
            "omplete_session(\n            p_message_id uuid,\n  "
            "          p_session_id uuid,\n            p_success"
            " boolean\n        )\n        \nRETURNS TABLE(\n    out"
            "come text,\n    message_id uuid,\n    conversation_i"
            "d uuid,\n    request_id uuid,\n    target_butler tex"
            "t,\n    target_kind text,\n    route_inbox_id uuid,\n"
            "    cancel_requested_at timestamptz,\n    cancel_co"
            "nfirmed_at timestamptz,\n    terminal_state text,\n "
            "   terminal_at timestamptz\n)\n\n        LANGUAGE plp"
            "gsql\n        SECURITY DEFINER\n        SET search_p"
            "ath = pg_catalog\n        "
        ),
        (
            "\n        #variable_conflict use_column\n        DEC"
            "LARE\n            v_turn public.dashboard_conversat"
            "ion_turns%ROWTYPE;\n            v_phase text;\n     "
            "       v_butler_name text;\n            v_invoke_cl"
            "aimed_at timestamptz;\n            v_cancel_acknowl"
            "edged_at timestamptz;\n            v_has_other_open"
            "_session boolean;\n            v_pending_terminal_s"
            "tate text;\n            p_outcome text;\n        BEG"
            "IN\n            SELECT * INTO v_turn\n            FR"
            "OM public.dashboard_conversation_turns\n           "
            " WHERE message_id = p_message_id\n            FOR U"
            "PDATE;\n            IF NOT FOUND THEN\n             "
            "   \nRETURN QUERY SELECT\n    'missing'::text,\n    N"
            "ULL::uuid,\n    NULL::uuid,\n    NULL::uuid,\n    NUL"
            "L::text,\n    NULL::text,\n    NULL::uuid,\n    NULL:"
            ":timestamptz,\n    NULL::timestamptz,\n    NULL::tex"
            "t,\n    NULL::timestamptz;\nRETURN;\n\n            END"
            " IF;\n            SELECT phase, butler_name, invoke"
            "_claimed_at, cancel_acknowledged_at\n            IN"
            "TO v_phase, v_butler_name, v_invoke_claimed_at, v_"
            "cancel_acknowledged_at\n            FROM public.das"
            "hboard_conversation_turn_sessions\n            WHER"
            "E message_id = p_message_id\n              AND sess"
            "ion_id = p_session_id;\n            IF NOT FOUND TH"
            "EN\n                p_outcome := 'conflict';\n      "
            "          \nRETURN QUERY SELECT\n    p_outcome,\n    "
            "v_turn.message_id,\n    v_turn.conversation_id,\n   "
            " v_turn.request_id,\n    v_turn.target_butler,\n    "
            "v_turn.target_kind,\n    v_turn.route_inbox_id,\n   "
            " v_turn.cancel_requested_at,\n    v_turn.cancel_con"
            "firmed_at,\n    v_turn.terminal_state,\n    v_turn.t"
            "erminal_at;\nRETURN;\n\n            END IF;\n         "
            "   PERFORM public.dashboard_turn_require_role('but"
            "ler_' || v_butler_name || '_rw');\n            UPDA"
            "TE public.dashboard_conversation_turn_sessions\n   "
            "         SET completed_at = coalesce(completed_at,"
            " now()),\n                invoke_active = FALSE,\n  "
            "              success = coalesce(success, p_succes"
            "s)\n            WHERE message_id = p_message_id\n   "
            "           AND session_id = p_session_id;\n        "
            "    SELECT EXISTS (\n                SELECT 1\n     "
            "           FROM public.dashboard_conversation_turn"
            "_sessions\n                WHERE message_id = p_mes"
            "sage_id\n                  AND completed_at IS NULL"
            "\n            ) INTO v_has_other_open_session;\n    "
            "        SELECT pending_terminal_state INTO v_pendi"
            "ng_terminal_state\n            FROM public.dashboar"
            "d_conversation_turns\n            WHERE message_id "
            "= p_message_id;\n\n            -- Cancellation inten"
            "t is not cancellation confirmation.  A runtime\n   "
            "         -- that was already invoking can still fi"
            "nish if its MCP cancel call\n            -- was unr"
            "eachable, so retain its actual success/failure her"
            "e.\n            IF v_turn.terminal_at IS NULL\n     "
            "           AND v_turn.cancel_requested_at IS NOT N"
            "ULL\n                AND NOT v_has_other_open_sessi"
            "on\n                AND (\n                    v_inv"
            "oke_claimed_at IS NULL\n                    OR v_ca"
            "ncel_acknowledged_at IS NOT NULL\n                )"
            " THEN\n                -- Either the Stop arrived b"
            "efore this session crossed invoke,\n               "
            " -- or this exact invoking session durably acknowl"
            "edged owner\n                -- cancellation before"
            " its final result was written.\n                UPD"
            "ATE public.dashboard_conversation_turns\n          "
            "      SET cancel_confirmed_at = coalesce(cancel_co"
            "nfirmed_at, now()),\n                    terminal_s"
            "tate = 'cancelled',\n                    terminal_a"
            "t = now(),\n                    updated_at = now()\n"
            "                WHERE message_id = p_message_id\n  "
            "              RETURNING * INTO v_turn;\n           "
            " ELSIF v_turn.terminal_at IS NULL\n                "
            "AND v_phase = 'route'\n                AND v_has_ot"
            "her_open_session THEN\n                -- The targe"
            "t completed before an overlapping classifier or\n  "
            "              -- recovery attempt. Hold its concre"
            "te outcome until the final\n                -- open"
            " session closes; no peer may be hidden by a termin"
            "al row.\n                UPDATE public.dashboard_co"
            "nversation_turns\n                SET pending_termi"
            "nal_state = CASE\n                        WHEN p_su"
            "ccess THEN 'completed'\n                        ELS"
            "E 'failed'\n                    END,\n              "
            "      pending_terminal_at = now(),\n               "
            "     updated_at = now()\n                WHERE mess"
            "age_id = p_message_id\n                RETURNING * "
            "INTO v_turn;\n            ELSIF v_turn.terminal_at "
            "IS NULL\n                AND NOT v_has_other_open_s"
            "ession\n                AND v_pending_terminal_stat"
            "e IS NOT NULL THEN\n                UPDATE public.d"
            "ashboard_conversation_turns\n                SET te"
            "rminal_state = v_pending_terminal_state,\n         "
            "           terminal_at = now(),\n                  "
            "  pending_terminal_state = NULL,\n                 "
            "   pending_terminal_at = NULL,\n                   "
            " updated_at = now()\n                WHERE message_"
            "id = p_message_id\n                RETURNING * INTO"
            " v_turn;\n            ELSIF v_turn.terminal_at IS N"
            "ULL\n                AND NOT v_has_other_open_sessi"
            "on\n                AND v_phase = 'route' THEN\n    "
            "            UPDATE public.dashboard_conversation_t"
            "urns\n                SET terminal_state = CASE WHE"
            "N p_success THEN 'completed' ELSE 'failed' END,\n  "
            "                  terminal_at = now(),\n           "
            "         updated_at = now()\n                WHERE "
            "message_id = p_message_id\n                RETURNIN"
            "G * INTO v_turn;\n            ELSIF v_turn.terminal"
            "_at IS NULL\n                AND NOT v_has_other_op"
            "en_session\n                AND v_phase = 'classifi"
            "cation'\n                AND v_turn.cancel_requeste"
            "d_at IS NOT NULL\n                AND v_turn.target"
            "_kind IS NULL THEN\n                -- Stop landed "
            "after a classifier invocation ended but before\n   "
            "             -- it could create any target action."
            " That invocation was not\n                -- killed"
            " (request_cancel reports ``settling`` in this race"
            "),\n                -- so record its actual non-del"
            "ivery as finished/failed rather\n                --"
            " than fabricating a confirmed cancellation or leav"
            "ing an\n                -- unresolvable open turn f"
            "orever.\n                UPDATE public.dashboard_co"
            "nversation_turns\n                SET terminal_stat"
            "e = 'failed',\n                    terminal_at = no"
            "w(),\n                    updated_at = now()\n      "
            "          WHERE message_id = p_message_id\n        "
            "        RETURNING * INTO v_turn;\n            END I"
            "F;\n            p_outcome := CASE\n                W"
            "HEN v_turn.terminal_state = 'cancelled' THEN 'canc"
            "elled'\n                WHEN v_turn.terminal_state "
            "= 'ambiguous' THEN 'ambiguous'\n                WHE"
            "N v_turn.terminal_at IS NOT NULL THEN 'finished'\n "
            "               WHEN v_turn.cancel_requested_at IS "
            "NOT NULL THEN 'cancelling'\n                ELSE 'a"
            "ctive'\n            END;\n            \nRETURN QUERY "
            "SELECT\n    p_outcome,\n    v_turn.message_id,\n    v"
            "_turn.conversation_id,\n    v_turn.request_id,\n    "
            "v_turn.target_butler,\n    v_turn.target_kind,\n    "
            "v_turn.route_inbox_id,\n    v_turn.cancel_requested"
            "_at,\n    v_turn.cancel_confirmed_at,\n    v_turn.te"
            "rminal_state,\n    v_turn.terminal_at;\nRETURN;\n\n   "
            "     END;\n        "
        ),
