            " v_turn.cancel_requested_at IS NOT NULL THEN\n     "
            "           p_outcome := 'cancelled';\n             "
            "   \nRETURN QUERY SELECT\n    p_outcome,\n    v_turn."
            "message_id,\n    v_turn.conversation_id,\n    v_turn"
