        (
            "\n        #variable_conflict use_column\n        DEC"
            "LARE\n            v_turn public.dashboard_conversat"
            "ion_turns%ROWTYPE;\n            v_has_open_session "
            "boolean;\n            p_outcome text;\n        BEGIN"
            "\n            -- Cancellation has a separate acknow"
            "ledgement protocol.  A target\n            -- runti"
            "me must not be able to bypass the other live sessi"
            "ons by\n            -- directly writing a terminal "
            "cancelled state.\n            IF p_state NOT IN ('c"
            "ompleted', 'failed') THEN\n                RAISE EX"
            "CEPTION 'invalid dashboard turn terminal state: %'"
            ", p_state\n                    USING ERRCODE = '220"
            "23';\n            END IF;\n            SELECT * INTO"
            " v_turn\n            FROM public.dashboard_conversa"
            "tion_turns\n            WHERE message_id = p_messag"
            "e_id\n            FOR UPDATE;\n            IF NOT FO"
            "UND THEN\n                \nRETURN QUERY SELECT\n    "
            "'missing'::text,\n    NULL::uuid,\n    NULL::uuid,\n "
            "   NULL::uuid,\n    NULL::text,\n    NULL::text,\n   "
            " NULL::uuid,\n    NULL::timestamptz,\n    NULL::time"
            "stamptz,\n    NULL::text,\n    NULL::timestamptz;\nRE"
            "TURN;\n\n            END IF;\n            IF v_turn.t"
            "arget_kind = 'route' AND v_turn.target_butler IS N"
            "OT NULL THEN\n                PERFORM public.dashbo"
            "ard_turn_require_role(\n                    'butler"
            "_' || v_turn.target_butler || '_rw'\n              "
            "  );\n            ELSE\n                -- Classific"
            "ation and terminal-action lanes are Switchboard-ow"
            "ned.\n                PERFORM public.dashboard_turn"
            "_require_role('butler_switchboard_rw');\n          "
            "  END IF;\n            IF v_turn.terminal_at IS NOT"
            " NULL THEN\n                p_outcome := CASE\n     "
            "               WHEN v_turn.terminal_state = 'cance"
            "lled' THEN 'cancelled'\n                    WHEN v_"
            "turn.terminal_state = 'ambiguous' THEN 'ambiguous'"
            "\n                    ELSE 'finished'\n             "
            "   END;\n                \nRETURN QUERY SELECT\n    p"
            "_outcome,\n    v_turn.message_id,\n    v_turn.conver"
            "sation_id,\n    v_turn.request_id,\n    v_turn.targe"
            "t_butler,\n    v_turn.target_kind,\n    v_turn.route"
            "_inbox_id,\n    v_turn.cancel_requested_at,\n    v_t"
            "urn.cancel_confirmed_at,\n    v_turn.terminal_state"
            ",\n    v_turn.terminal_at;\nRETURN;\n\n            END"
            " IF;\n            SELECT EXISTS (\n                S"
            "ELECT 1\n                FROM public.dashboard_conv"
            "ersation_turn_sessions\n                WHERE messa"
            "ge_id = p_message_id\n                  AND complet"
            "ed_at IS NULL\n            ) INTO v_has_open_sessio"
            "n;\n            IF p_state <> 'cancelled' AND v_has"
            "_open_session THEN\n                UPDATE public.d"
            "ashboard_conversation_turns\n                SET pe"
            "nding_terminal_state = p_state,\n                  "
            "  pending_terminal_at = now(),\n                   "
            " updated_at = now()\n                WHERE message_"
            "id = p_message_id\n                RETURNING * INTO"
            " v_turn;\n                p_outcome := 'pending';\n "
            "               \nRETURN QUERY SELECT\n    p_outcome,"
            "\n    v_turn.message_id,\n    v_turn.conversation_id"
            ",\n    v_turn.request_id,\n    v_turn.target_butler,"
            "\n    v_turn.target_kind,\n    v_turn.route_inbox_id"
            ",\n    v_turn.cancel_requested_at,\n    v_turn.cance"
            "l_confirmed_at,\n    v_turn.terminal_state,\n    v_t"
            "urn.terminal_at;\nRETURN;\n\n            END IF;\n    "
            "        UPDATE public.dashboard_conversation_turns"
            "\n            SET terminal_state = CASE\n           "
            "         WHEN cancel_requested_at IS NOT NULL THEN"
            " 'cancelled'\n                    ELSE p_state\n    "
            "            END,\n                terminal_at = now"
            "(),\n                updated_at = now()\n           "
            " WHERE message_id = p_message_id\n            RETUR"
            "NING * INTO v_turn;\n            p_outcome := CASE\n"
            "                WHEN v_turn.terminal_state = 'canc"
            "elled' THEN 'cancelled'\n                WHEN v_tur"
            "n.terminal_state = 'ambiguous' THEN 'ambiguous'\n  "
            "              ELSE 'finished'\n            END;\n   "
            "         \nRETURN QUERY SELECT\n    p_outcome,\n    v"
            "_turn.message_id,\n    v_turn.conversation_id,\n    "
            "v_turn.request_id,\n    v_turn.target_butler,\n    v"
            "_turn.target_kind,\n    v_turn.route_inbox_id,\n    "
            "v_turn.cancel_requested_at,\n    v_turn.cancel_conf"
            "irmed_at,\n    v_turn.terminal_state,\n    v_turn.te"
            "rminal_at;\nRETURN;\n\n        END;\n        "
        ),
