            " NULL::text,\n    NULL::uuid,\n    NULL::timestamptz"
            ",\n    NULL::timestamptz,\n    NULL::text,\n    NULL:"
            ":timestamptz;\nRETURN;\n\n            END IF;\n       "
            "     IF v_turn.terminal_at IS NOT NULL\n           "
