            "ersation_id,\n    v_turn.request_id,\n    v_turn.tar"
            "get_butler,\n    v_turn.target_kind,\n    v_turn.rou"
            "te_inbox_id,\n    v_turn.cancel_requested_at,\n    v"
            "_turn.cancel_confirmed_at,\n    v_turn.terminal_sta"
            "te,\n    v_turn.terminal_at;\nRETURN;\n\n            E"
            "ND IF;\n            UPDATE public.dashboard_convers"
            "ation_turns\n            SET cancel_requested_at = "
            "coalesce(cancel_requested_at, now()),\n            "
            "    updated_at = now()\n            WHERE message_i"
            "d = p_message_id\n            RETURNING * INTO v_tu"
            "rn;\n            SELECT EXISTS (\n                SE"
            "LECT 1\n                FROM public.dashboard_conve"
            "rsation_turn_sessions\n                WHERE messag"
            "e_id = p_message_id\n                  AND complete"
            "d_at IS NULL\n                  AND invoke_active I"
            "S TRUE\n            ) INTO v_has_active_invocation;"
            "\n            SELECT EXISTS (\n                SELEC"
            "T 1\n                FROM public.dashboard_conversa"
            "tion_turn_sessions\n                WHERE message_i"
            "d = p_message_id\n                  AND invoke_clai"
            "med_at IS NOT NULL\n            ) INTO v_has_prior_"
            "invocation;\n            IF v_turn_is_ambiguous THE"
            "N\n                -- Keep the no-replay terminal f"
            "act, but still address every\n                -- ex"
            "act active predecessor through the normal Stop API"
            ".\n                p_outcome := CASE\n              "
            "      WHEN v_has_active_invocation THEN 'cancellin"
            "g'\n                    ELSE 'ambiguous'\n          "
            "      END;\n                \nRETURN QUERY SELECT\n  "
            "  p_outcome,\n    v_turn.message_id,\n    v_turn.con"
            "versation_id,\n    v_turn.request_id,\n    v_turn.ta"
            "rget_butler,\n    v_turn.target_kind,\n    v_turn.ro"
            "ute_inbox_id,\n    v_turn.cancel_requested_at,\n    "
            "v_turn.cancel_confirmed_at,\n    v_turn.terminal_st"
            "ate,\n    v_turn.terminal_at;\nRETURN;\n\n            "
            "END IF;\n            IF NOT v_has_active_invocation"
            "\n                AND NOT v_has_prior_invocation\n  "
            "              AND v_turn.ingress_state = 'submitti"
            "ng' THEN\n                -- The generator has clai"
