        (
            "CREATE OR REPLACE FUNCTION public.runtime_probe_co"
            "ntrol_receipt_retention()\n        RETURNS trigger\n"
            "        LANGUAGE plpgsql\n        SET search_path ="
            " pg_catalog, public\n        "
        ),
        (
            "\n        BEGIN\n            IF OLD.capability_exp >"
            "= now() - INTERVAL '5 seconds' THEN\n              "
            "  RAISE EXCEPTION\n                    'runtime-pro"
            "be control receipt is still within its replay wind"
            "ow';\n            END IF;\n            RETURN OLD;\n "
            "       END\n        "
        ),
