    (
        "public",
        "cost_claim_audit_claim",
        "",
        (
            "CREATE OR REPLACE FUNCTION public.cost_claim_audit"
            "_claim() RETURNS trigger\n        LANGUAGE plpgsql "
        ),
        (
            "\n        BEGIN\n            IF current_user = (\n   "
            "                SELECT pg_get_userbyid(c.relowner)"
            "\n                   FROM pg_class AS c\n           "
            "        WHERE c.oid = TG_RELID\n               )\n  "
            "             AND current_setting('butlers.cost_cla"
            "im_restore', true) = 'on'\n            THEN\n       "
            "         RETURN NEW;\n            END IF;\n         "
            "   INSERT INTO public.cost_claim_events\n          "
            "      (claim_id, actor_role, action, old_state, ne"
            "w_state, idempotency_key)\n            VALUES (\n   "
            "             NEW.id, current_user,\n               "
            " CASE WHEN TG_OP = 'INSERT' THEN 'asserted'\n      "
            "               WHEN NEW.retracted_at IS DISTINCT F"
            "ROM OLD.retracted_at THEN 'retracted'\n            "
            "         WHEN NEW.superseded_at IS DISTINCT FROM O"
            "LD.superseded_at THEN 'superseded'\n               "
            "      ELSE 'amended' END,\n                CASE WHE"
            "N TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL EN"
            "D,\n                to_jsonb(NEW), gen_random_uuid("
            ")::text\n            );\n            RETURN NEW;\n   "
            "     END "
        ),
    ),
