            "ion IS DISTINCT FROM p->>'key_generation' THEN RET"
            'URN \'{"error":"AUTH_UNAVAILABLE"}\'; END IF;\n  UPDA'
            "TE dashboard_auth.contexts SET revoked=true WHERE "
            "NOT revoked;\n  UPDATE dashboard_auth.intents SET c"
            "onsumed=true,authorized=false WHERE NOT consumed;\n"
            "  UPDATE dashboard_auth.ceremonies SET consumed=tr"
            "ue WHERE NOT consumed;\n  INSERT INTO dashboard_aut"
            "h.audit(action,outcome,actor) VALUES(action,'succe"
            "ss','host_operator');\n  RETURN jsonb_build_object("
            "'operation',action,'canonical_origin',s.origin,'ch"
            "anged',true);\n END IF;\n IF action='revoke_sessions"
            "' THEN\n  IF NOT COALESCE((p->>'confirm_revoke')::b"
            'oolean,false) THEN RETURN \'{"error":"FORBIDDEN"}\';'
            " END IF;\n  IF s.key_generation IS DISTINCT FROM p-"
            ">>'key_generation' THEN RETURN '{\"error\":\"AUTH_UNA"
            "VAILABLE\"}'; END IF;\n  UPDATE dashboard_auth.insta"
            "nce SET session_epoch=session_epoch+1 WHERE single"
            "ton;\n  UPDATE dashboard_auth.sessions SET revoked="
            "true WHERE NOT revoked;\n  UPDATE dashboard_auth.ce"
            "remonies SET consumed=true WHERE operation='login'"
            " AND NOT consumed;\n  INSERT INTO dashboard_auth.au"
            "dit(action,outcome,actor) VALUES(action,'success',"
            "'host_operator');\n  RETURN jsonb_build_object('ope"
            "ration',action,'canonical_origin',s.origin,'change"
            "d',true);\n END IF;\n IF action IN ('reconcile_mode'"
