        (
            "\n        BEGIN\n            IF NEW.rebind_id IS DIS"
            "TINCT FROM OLD.rebind_id\n               OR NEW.sou"
            "rce_entity_id IS DISTINCT FROM OLD.source_entity_i"
            "d\n               OR NEW.target_entity_id IS DISTIN"
            "CT FROM OLD.target_entity_id\n               OR NEW"
            ".target_schema IS DISTINCT FROM OLD.target_schema\n"
            "            THEN\n                RAISE EXCEPTION '"
            "entity rebind receipt identity is immutable';\n    "
            "        END IF;\n            RETURN NEW;\n        EN"
            "D\n        "
        ),
