    (
        "public",
        "resolve_health_medication_refill",
        "text,numeric,numeric",
        (
            "CREATE OR REPLACE FUNCTION public.resolve_health_m"
            "edication_refill(\n    p_subject text,\n    p_doses_"
            "per_day numeric,\n    p_warning_days numeric\n)\nRETU"
            "RNS boolean\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFIN"
            "ER\nSET search_path = pg_catalog, pg_temp\n"
        ),
        (
            "\nDECLARE\n    v_id uuid;\n    v_validity text;\n    v"
            "_meta jsonb;\n    v_doses bigint;\nBEGIN\n    SELECT "
            "f.id, f.validity, f.metadata INTO v_id, v_validity"
            ", v_meta\n    FROM health.facts f\n    WHERE f.predi"
            "cate = 'medication'\n      AND f.scope = 'health'\n "
            "     AND f.subject = p_subject\n    ORDER BY (f.val"
            "idity = 'active') DESC, f.created_at DESC\n    LIMI"
            "T 1;\n    IF NOT FOUND THEN\n        RETURN NULL;\n  "
            "  END IF;\n    IF NOT (v_validity = 'active' AND CO"
            "ALESCE((v_meta ->> 'active')::boolean, false)) THE"
            "N\n        RETURN false;\n    END IF;\n    IF v_meta "
            "->> 'quantity' IS NULL\n       OR v_meta ->> 'quant"
            "ity_updated_at' IS NULL\n       OR p_doses_per_day "
            "IS NULL\n       OR p_doses_per_day <= 0\n       OR p"
            "_warning_days IS NULL THEN\n        RETURN NULL;\n  "
            "  END IF;\n    SELECT count(*) INTO v_doses\n    FRO"
            "M health.facts d\n    WHERE d.predicate = 'took_dos"
            "e'\n      AND d.scope = 'health'\n      AND d.validi"
            "ty = 'active'\n      AND d.metadata ->> 'medication"
            "_id' = v_id::text\n      AND d.valid_at >= (v_meta "
            "->> 'quantity_updated_at')::timestamptz\n      AND "
            "COALESCE((d.metadata ->> 'skipped')::boolean, fals"
            "e) = false;\n    RETURN GREATEST(0, ((v_meta ->> 'q"
            "uantity')::numeric - v_doses) / p_doses_per_day)\n "
            "          <= p_warning_days;\nEND;\n"
        ),
    ),
