        "public",
        "register_butler_boot",
        "text,uuid",
        (
            "CREATE OR REPLACE FUNCTION public.register_butler_"
            "boot(\n            p_name text, p_instance uuid\n   "
            "     ) RETURNS bigint\n        LANGUAGE plpgsql SEC"
            "URITY DEFINER\n        SET search_path = pg_catalog"
            ", switchboard, pg_temp\n        "
        ),
        (
            "\n        DECLARE\n            v_epoch bigint;\n     "
            "       v_current_epoch bigint;\n            v_curre"
            "nt_instance uuid;\n            v_prior_epoch bigint"
            ";\n        BEGIN\n            IF p_instance IS NULL "
            "OR p_name IS NULL\n               OR current_settin"
            "g('role', true) IS DISTINCT FROM\n                 "
            "   'butler_' || p_name || '_rw' THEN\n             "
            "   RAISE EXCEPTION 'boot registration requires the"
            " matching runtime role'\n                    USING "
            "ERRCODE = '42501';\n            END IF;\n           "
            " IF NOT EXISTS (\n                SELECT 1 FROM swi"
            "tchboard.butler_registry WHERE name = p_name\n     "
            "       ) THEN\n                RAISE EXCEPTION 'unk"
            "nown roster registration'\n                    USIN"
            "G ERRCODE = '22023';\n            END IF;\n         "
            "   INSERT INTO switchboard.butler_registry_control"
            "_plane (name)\n            VALUES (p_name) ON CONFL"
            "ICT (name) DO NOTHING;\n            SELECT boot_epo"
            "ch, boot_instance_id\n              INTO v_current_"
            "epoch, v_current_instance\n              FROM switc"
            "hboard.butler_registry_control_plane\n             "
            "WHERE name = p_name\n             FOR UPDATE;\n     "
            "       SELECT boot_epoch INTO v_prior_epoch\n      "
            "        FROM switchboard.butler_boot_registrations"
            "\n             WHERE name = p_name AND boot_instanc"
            "e_id = p_instance;\n            IF v_prior_epoch IS"
            " NOT NULL THEN\n                IF v_prior_epoch = "
            "v_current_epoch\n                   AND v_current_i"
            "nstance = p_instance THEN\n                    RETU"
            "RN v_prior_epoch;\n                END IF;\n        "
            "        RAISE EXCEPTION 'superseded boot registrat"
            "ion cannot become current'\n                    USI"
            "NG ERRCODE = '55000';\n            END IF;\n        "
            "    v_epoch := v_current_epoch + 1;\n            IN"
            "SERT INTO switchboard.butler_boot_registrations (\n"
            "                name, boot_instance_id, boot_epoch"
            "\n            ) VALUES (p_name, p_instance, v_epoch"
            ");\n            UPDATE switchboard.butler_registry_"
            "control_plane\n               SET boot_epoch = v_ep"
            "och,\n                   boot_instance_id = p_insta"
            "nce,\n                   observed_state = 'observer"
            "_unknown',\n                   observed_boot_epoch "
            "= NULL,\n                   route_compatible = NULL"
            ",\n                   accepting_routes = NULL,\n    "
            "               probe_failure_class = NULL,\n       "
            "            updated_at = clock_timestamp()\n       "
            "      WHERE name = p_name;\n            RETURN v_ep"
            "och;\n        END;\n        "
        ),
