    (
        "switchboard",
        "goal_ledger_immutable",
        "",
        (
            "CREATE OR REPLACE FUNCTION switchboard.goal_ledger"
            "_immutable()\n        RETURNS trigger LANGUAGE plpg"
            "sql SET search_path=pg_catalog "
        ),
        (
            "\n        BEGIN\n            IF TG_TABLE_NAME='admis"
            "sion_decisions' THEN\n                RAISE EXCEPTI"
            "ON 'Admission history is immutable';\n            E"
            "LSIF TG_TABLE_NAME='goals' THEN\n                --"
            " thread_id may be bound once, after admission; nev"
            "er rebound.\n                IF (to_jsonb(NEW) - AR"
            "RAY['status','exposed','thread_id','updated_at'])\n"
            "                   IS DISTINCT FROM\n              "
            "     (to_jsonb(OLD) - ARRAY['status','exposed','th"
            "read_id','updated_at'])\n                   OR (OLD"
            ".exposed AND NOT NEW.exposed)\n                   O"
            "R (OLD.thread_id IS NOT NULL\n                     "
            "  AND NEW.thread_id IS DISTINCT FROM OLD.thread_id"
            ") THEN\n                    RAISE EXCEPTION 'Goal a"
            "uthority and source association are immutable';\n  "
            "              END IF;\n            ELSIF TG_TABLE_N"
            "AME='invocations' THEN\n                IF (NEW.goa"
            "l_id,NEW.parent_invocation_id,NEW.depth,NEW.role,N"
            "EW.lead_epoch,\n                    NEW.grant_snaps"
            "hot,NEW.grant_digest,NEW.max_turns,NEW.max_tokens)"
            " IS DISTINCT FROM\n                   (OLD.goal_id,"
            "OLD.parent_invocation_id,OLD.depth,OLD.role,OLD.le"
            "ad_epoch,\n                    OLD.grant_snapshot,O"
            "LD.grant_digest,OLD.max_turns,OLD.max_tokens)\n    "
            "               OR (OLD.exposed AND NOT NEW.exposed"
            ") THEN\n                    RAISE EXCEPTION 'Invoca"
            "tion lineage, grant and exposure are immutable';\n "
            "               END IF;\n            ELSIF TG_TABLE_"
            "NAME='goal_inbox' THEN\n                IF (to_json"
            "b(NEW) - 'consumed_at') IS DISTINCT FROM (to_jsonb"
            "(OLD) - 'consumed_at')\n                   OR (OLD."
            "consumed_at IS NOT NULL\n                       AND"
            " NEW.consumed_at IS DISTINCT FROM OLD.consumed_at)"
            " THEN\n                    RAISE EXCEPTION 'Goal in"
            "box delivery is immutable';\n                END IF"
            ";\n            ELSIF TG_TABLE_NAME='effects' THEN\n "
            "               IF (NEW.goal_id,NEW.invocation_id,N"
            "EW.capability,NEW.args_digest,\n                   "
            " NEW.delivery_ref,NEW.recipient_entity,NEW.recipie"
            "nt_channel) IS DISTINCT FROM\n                   (O"
            "LD.goal_id,OLD.invocation_id,OLD.capability,OLD.ar"
            "gs_digest,\n                    OLD.delivery_ref,OL"
            "D.recipient_entity,OLD.recipient_channel) THEN\n   "
            "                 RAISE EXCEPTION 'Effect lineage a"
            "nd recipient association are immutable';\n         "
            "       END IF;\n            END IF;\n            RET"
            "URN NEW;\n        END "
        ),
    ),
