def _ordinary_policy_sql(policy, target, migration_owner):
    from .apply import quote_identifier

    command = {"*": "ALL", "r": "SELECT", "a": "INSERT", "w": "UPDATE", "d": "DELETE"}[
        policy["command"]
    ]
    roles = ",".join(
        "PUBLIC" if role == "PUBLIC" else quote_identifier(role) for role in policy["roles"]
    )
    sql = f"CREATE POLICY {quote_identifier(policy['name'])} ON {target} FOR {command} TO {roles}"
    for field, clause in (("using", " USING "), ("check", " WITH CHECK ")):
        tokens = policy[field]
        if tokens is not None:
            tokens = [
                "'" + migration_owner.replace("'", "''") + "'"
                if token == "'__NORMAL_OWNER__'"
                else token
                for token in tokens
            ]
            sql += clause + "(" + " ".join(tokens) + ")"
    return sql


def ordinary_security_policy_changes(manifest):
    from .grants import compiled_security_contract

    def indexed(previous):
        return {
            (row["schema"], row["table"], row["name"]): row
            for row in compiled_security_contract(manifest, ordinary_purposes=not previous)[
                "policies"
            ]
        }

    before, after = indexed(True), indexed(False)
    return {
        key: (before.get(key), after.get(key))
        for key in before.keys() | after.keys()
        if before.get(key) != after.get(key)
    }


def converge_ordinary_security_policies(connection, manifest, *, predecessor=False, only=None):
    """Install only the enumerated purpose policies after exact shape preflight.

    Unknown policies never enter this plan. The held migration transaction has
    already proved every old/new policy and trigger before the first mutation.
    """
    from .apply import quote_identifier

    changes = ordinary_security_policy_changes(manifest)
    if changes:
        require_maintenance(connection)
    for (schema, table, name), (before, after) in sorted(changes.items()):
        if only is not None and (schema, table) not in only:
            continue
        target = quote_identifier(schema) + "." + quote_identifier(table)
        connection.exec_driver_sql(f"DROP POLICY IF EXISTS {quote_identifier(name)} ON {target}")
        row = before if predecessor else after
        if row is not None:
            connection.exec_driver_sql(_ordinary_policy_sql(row, target, manifest.migration_owner))


def verify_declared_security_shapes(
    connection,
    manifest,
    observed,
    *,
    exclude_protected=False,
    retired_marker_verified=False,
    allow_previous_ordinary=False,
):
    """Accept only a complete source-current or exact pre-owner-transition shape."""
    from .roles import AuthorityError

    try:
        _verify_declared_security_shapes(
            connection,
            manifest,
            observed,
            exclude_protected=exclude_protected,
            retired_marker_verified=retired_marker_verified,
        )
    except AuthorityError as exc:
        if (
            not allow_previous_ordinary
            or str(exc)
            not in {
                "Database policy definition differs from source",
                "Database security definition is not declared",
            }
            or getattr(exc, "__notes__", ())
        ):
            raise
        _verify_declared_security_shapes(
            connection,
            manifest,
            observed,
            exclude_protected=exclude_protected,
            retired_marker_verified=retired_marker_verified,
            ordinary_purposes=False,
        )


def _verify_declared_security_shapes(
    connection,
    manifest,
    observed,
    *,
    exclude_protected=False,
    retired_marker_verified=False,
    ordinary_purposes=True,
):
    """Parse fixed ordinary policies/triggers on owned scratch relations.

    PostgreSQL compares both parsed sides; no application values are read or
    copied. The exact temporary relation name preserves correlated row names in
    policy subqueries. An existing temporary object is never adopted/dropped.
    This is a controlled maintenance precondition, never a serving DDL path.
    """
    from sqlalchemy import text

    from .apply import quote_identifier
    from .grants import compiled_security_contract
    from .roles import AuthorityError

    require_maintenance(connection)
    expected = compiled_security_contract(manifest, ordinary_purposes=ordinary_purposes)
    protected = {(schema, name) for _, schema, name, _, _ in _PROTECTED_TABLE_SHAPES}
    for row in observed:
        key = row["schema"], row["name"]
        if exclude_protected and key in protected:
            continue
        target = quote_identifier(row["schema"]) + "." + quote_identifier(row["name"])
        policies = [item for item in expected["policies"] if (item["schema"], item["table"]) == key]
        triggers = [item for item in expected["triggers"] if (item["schema"], item["table"]) == key]
        actual_policies = _shape_rows(connection, _SHAPE_POLICIES, target)
        actual_triggers = _shape_rows(connection, _SHAPE_TRIGGERS, target)
        if retired_marker_verified and key == ("public", "model_dispatch_attempts"):
            # The caller already bound the complete predecessor function, table,
            # timing and condition through inspect_retired_interfaces. Nothing
            # else is admitted by this temporary pre-retirement exclusion.
            actual_triggers = tuple(
                row
                for row in actual_triggers
                if row["tgname"] != "runtime_attention_plant_legacy_debounce_marker_trigger"
            )
        if not policies and not triggers:
            if actual_policies or actual_triggers:
                raise AuthorityError("Database security definition is not declared")
            continue
        scratch = "pg_temp." + quote_identifier(row["name"])
        if (
            connection.execute(
                text("SELECT pg_catalog.to_regclass(:relation) IS NOT NULL"), {"relation": scratch}
            ).scalar_one()
            is not False
        ):
            raise AuthorityError("Database security parser target is unavailable")
        created = False
        primary = None
        try:
            connection.exec_driver_sql(
                f"CREATE TEMPORARY TABLE {quote_identifier(row['name'])} (LIKE {target})"
            )
            created = True
            for policy in policies:
                command = {"*": "ALL", "r": "SELECT", "a": "INSERT", "w": "UPDATE", "d": "DELETE"}[
                    policy["command"]
                ]
                roles = ",".join(
                    "PUBLIC" if role == "PUBLIC" else quote_identifier(role)
                    for role in policy["roles"]
                )
                sql = (
                    f"CREATE POLICY {quote_identifier(policy['name'])} ON {scratch} "
                    f"FOR {command} TO {roles}"
                )
                for field, clause in (("using", " USING "), ("check", " WITH CHECK ")):
                    tokens = policy[field]
                    if tokens is not None:
                        tokens = [
                            "'" + manifest.migration_owner.replace("'", "''") + "'"
                            if token == "'__NORMAL_OWNER__'"
                            else token
                            for token in tokens
                        ]
                        sql += clause + "(" + " ".join(tokens) + ")"
                connection.exec_driver_sql(sql)
            for trigger in triggers:
                events = trigger["type"]
                timing = "BEFORE" if events & 2 else "AFTER"
                commands = []
                for bit, command in (
                    (4, "INSERT"),
                    (8, "DELETE"),
                    (16, "UPDATE"),
                    (32, "TRUNCATE"),
                ):
                    if events & bit:
                        if command == "UPDATE" and trigger["columns"]:
                            command += " OF " + ",".join(map(quote_identifier, trigger["columns"]))
                        commands.append(command)
                constraint = "CONSTRAINT " if trigger["constraint"] else ""
                defer = " DEFERRABLE INITIALLY DEFERRED" if trigger["constraint"] else ""
                per = "ROW" if events & 1 else "STATEMENT"
                when = " WHEN " + " ".join(trigger["when"]) if trigger["when"] is not None else ""
                function = (
                    quote_identifier(trigger["function_schema"])
                    + "."
                    + quote_identifier(trigger["function_name"])
                )
                connection.exec_driver_sql(
                    f"CREATE {constraint}TRIGGER {quote_identifier(trigger['name'])} {timing} "
                    + " OR ".join(commands)
                    + f" ON {scratch}{defer} FOR EACH {per}{when} EXECUTE FUNCTION {function}()"
                )
                if trigger["enabled"] == "A":
                    connection.exec_driver_sql(
                        f"ALTER TABLE {scratch} ENABLE ALWAYS TRIGGER "
                        f"{quote_identifier(trigger['name'])}"
                    )
            if actual_policies != _shape_rows(connection, _SHAPE_POLICIES, scratch):
                raise AuthorityError("Database policy definition differs from source")
            if actual_triggers != _shape_rows(connection, _SHAPE_TRIGGERS, scratch):
                raise AuthorityError("Database trigger definition differs from source")
        except BaseException as exc:
            primary = exc
            raise
        finally:
            if created:
                try:
                    connection.exec_driver_sql(f"DROP TABLE {scratch}")
                except BaseException:
                    if primary is None:
                        raise
                    primary.add_note("Database security parser cleanup was incomplete")


